import { Book } from "@/lib/types";

export const daniel: Book = {
  id: "daniel",
  name: "Daniel",
  shortName: "Dan",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Im dritten Jahr der Regierung Jojakims, des Königs von Juda*, kam Nebukadnezar, der König von Babel, nach Jerusalem und belagerte es*.", heading: "Daniel und seine Freunde am Königshof in Babel", footnotes: ["℘ 2Kö 23,36", "℘ 2Kö 24,1.2"] },
      { number: 2, text: "Und der Herr gab Jojakim, den König von Juda, in seine Hand und einen Teil der Geräte des Hauses Gottes. Und er brachte sie ins Land Schinar*, in das Haus seines Gottes: die Geräte brachte er in das Schatzhaus seines Gottes*.", footnotes: ["d. i. die Ebene Babyloniens, die zwischen Euphrat und Tigris liegt\n℘ 1Mo 10,10; 11,2; Jes 11,11; Sach 5,11", "℘ Kap. 5,2.3; 2Chr 36,5-7.10"] },
      { number: 3, text: "Und der König befahl dem Aschpenas, dem Obersten seiner Hofbeamten*, er solle <einige> von den Söhnen Israel bringen, und <zwar> vom königlichen Geschlecht und von den Vornehmen*:", footnotes: ["w. Eunuchen", "℘ 5Mo 28,41; 2Kö 20,18; Jes 39,6.7"] },
      { number: 4, text: "junge Männer, an denen keinerlei Makel sei, von schönem Aussehen und verständig in aller Weisheit, gebildet und von guter Auffassungsgabe, und die <somit> fähig seien*, im Palast des Königs zu dienen*; und man solle sie Schrift und Sprache der Chaldäer lehren.", footnotes: ["w. verständig in aller Weisheit, Erkenntnis erkennend, Einsicht habend <in> Kenntnis, und in denen die Fähigkeit <sei>", "w. zu stehen\n℘ V. 19; 1Mo 41,46; Spr 22,29"] },
      { number: 5, text: "Und der König bestimmte ihre tägliche Versorgung* von der Tafelkost des Königs und von dem Wein, den er trank, und dass man sie drei Jahre lang erziehen solle; und nach deren Ablauf sollten sie in den Dienst des Königs treten*.", footnotes: ["w. bestimmte ihnen die Sache des Tages an ihrem Tag", "w. vor dem König stehen"] },
      { number: 6, text: "Und unter ihnen waren von den Söhnen Juda: Daniel, Hananja, Mischaël und Asarja*.", footnotes: ["℘ Kap. 2,17; 5,13; 6,14"] },
      { number: 7, text: "Und der Oberste der Hofbeamten* gab ihnen <andere> Namen*; er nannte Daniel Beltschazar*, Hananja Schadrach, Mischaël Meschach und Asarja Abed-Nego.", footnotes: ["w. Eunuchen", "℘ 1Mo 41,45; 2Kö 24,17", "℘ Kap. 4,5; 5,12; 10,1"] },
      { number: 8, text: "Aber Daniel nahm sich in seinem Herzen vor, sich nicht mit der Tafelkost des Königs und mit dem Wein, den er trank, unrein zu machen; und er erbat sich vom Obersten der Hofbeamten*, dass er sich nicht unrein machen müsse*.", footnotes: ["w. Eunuchen", "℘ Hes 4,13"] },
      { number: 9, text: "Und Gott gab Daniel Gnade und Erbarmen vor dem Obersten der Hofbeamten*.", footnotes: ["w. Eunuchen\n℘ 1Mo 39,21; Est 2,9"] },
      { number: 10, text: "Und der Oberste der Hofbeamten* sagte zu Daniel: Ich fürchte meinen Herrn, den König, der eure Speise und euer Getränk bestimmt hat. Denn warum sollte er sehen, dass eure Gesichter schlechter aussehen* als die der jungen Männer eures Alters, so dass ihr meinen Kopf beim König verwirktet*?", footnotes: ["w. Eunuchen", "o. magerer sind", "o. in Schuld brächtet"] },
      { number: 11, text: "Da sagte Daniel zu dem Aufseher, den der Oberste der Hofbeamten* über Daniel, Hananja, Mischaël und Asarja bestellt hatte:", footnotes: ["w. Eunuchen"] },
      { number: 12, text: "Versuche es doch zehn Tage <lang> mit deinen Knechten, dass man uns Gemüse zu essen und Wasser zu trinken gebe!" },
      { number: 13, text: "Und dann möge unser Aussehen und das Aussehen der jungen Männer, die die Tafelkost des Königs essen, von dir geprüft* werden! Dann verfahre mit deinen Knechten je nachdem, was du sehen wirst!", footnotes: ["w. vor dir betrachtet"] },
      { number: 14, text: "Und er hörte auf sie in dieser Sache und versuchte es zehn Tage mit ihnen." },
      { number: 15, text: "Und am Ende der zehn Tage zeigte sich ihr Aussehen schöner und wohlgenährter* als das aller jungen Männer, die die Tafelkost des Königs aßen.", footnotes: ["w. fetter an Fleisch"] },
      { number: 16, text: "Da nahm der Aufseher ihre Tafelkost und den Wein, den sie trinken sollten, weg und gab ihnen Gemüse." },
      { number: 17, text: "Und diesen vier jungen Männern, ihnen gab Gott Kenntnis und Verständnis in jeder Schrift und Weisheit*; und Daniel verstand sich auf Visionen und Träume jeder Art*.", footnotes: ["℘ 1Kö 3,12", "℘ Kap. 2,19; 4,6; 5,12; 10,1; 1Mo 41,12; 2Chr 26,5"] },
      { number: 18, text: "Und am Ende der Tage, nach denen der König sie <zu sich> zu bringen befohlen hatte, brachte der Oberste der Hofbeamten* sie vor Nebukadnezar.", footnotes: ["w. Eunuchen"] },
      { number: 19, text: "Und der König redete mit ihnen; und unter ihnen allen wurde niemand gefunden<, der> wie Daniel, Hananja, Mischaël und Asarja <gewesen wäre>. Und sie dienten dem König*.", footnotes: ["w. sie standen vor dem König\n℘ Spr 22,29"] },
      { number: 20, text: "Und in jeder Angelegenheit, die der König von ihnen erfragte und die ein verständiges Urteil erforderte*, fand er sie allen Wahrsagepriestern* und Beschwörern, die in seinem ganzen Königreich waren, zehnfach überlegen. —", footnotes: ["w. Und jede Sache von Weisheit des Verständnisses, die der König von ihnen suchte", "o. Geheimgelehrten. — Das sind Gelehrte, die zugleich Zauberer sind."] },
      { number: 21, text: "Und Daniel blieb bis zum ersten Jahr des Königs Kyrus.*", footnotes: ["℘ Kap. 6,29; 10,1; Esr 1,1.2"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und im zweiten Jahr der Regierung Nebukadnezars* hatte Nebukadnezar Träume, so dass sein Geist beunruhigt wurde und sein Schlaf für ihn dahin war.*", heading: "Nebukadnezars Traum von dem großen Standbild", footnotes: ["℘ Jer 25,1", "℘ Kap. 4,2; 7,15; 1Mo 41,8"] },
      { number: 2, text: "Und der König befahl, dass man die Wahrsagepriester*, die Beschwörer, die Zauberer und die Sterndeuter* rufen sollte, dem König seine Träume mitzuteilen*. Da kamen sie und traten vor den König.", footnotes: ["o. Geheimgelehrten. — Das sind Gelehrte, die zugleich Zauberer sind.", "hebr. Chaldäer. — Der Volksname Chaldäer wurde eine Berufsbezeichnung für Astrologen.\n℘ Est 1,13", "℘ Kap. 4,3; 5,7; 1Sam 6,2"] },
      { number: 3, text: "Und der König sprach zu ihnen: Ich habe einen Traum gehabt, und mein Geist ist beunruhigt, den Traum zu verstehen*.", footnotes: ["o. erkennen"] },
      { number: 4, text: "Da sagten die Sterndeuter* zum König auf Aramäisch*: König, lebe ewig!* Sage deinen Knechten den Traum! Dann wollen wir die Deutung kundtun.", footnotes: ["hebr. Chaldäer. — Der Volksname Chaldäer wurde eine Berufsbezeichnung für Astrologen.", "Von hier an bis einschließlich Kap. 7,28 ist das Danielbuch nicht in hebräischer, sondern in aramäischer Sprache geschrieben.\n℘ Jes 36,11", "℘ Kap. 3,9; 5,10; 6,7.22; 1Kö 1,31"] },
      { number: 5, text: "Der König antwortete und sprach zu den Sterndeutern*: Die Sache ist von mir fest beschlossen*: Wenn ihr mir den Traum und seine Deutung nicht mitteilt, <dann> werdet ihr in Stücke gehauen, und eure Häuser werden zu einem Misthaufen gemacht*.", footnotes: ["hebr. Chaldäer. — Der Volksname Chaldäer wurde eine Berufsbezeichnung für Astrologen.", "w. verkündet", "℘ Kap. 3,29; Esr 6,11"] },
      { number: 6, text: "Wenn ihr aber den Traum und seine Deutung kundtut, werdet ihr Geschenke, Gaben und große Ehre von mir empfangen*. Darum tut mir den Traum und seine Deutung kund!", footnotes: ["℘ V. 48; Kap. 5,16"] },
      { number: 7, text: "Sie antworteten zum zweiten Mal und sagten: Der König sage seinen Knechten den Traum! Dann tun wir die Deutung kund." },
      { number: 8, text: "Der König antwortete und sprach: Ich weiß zuverlässig, dass ihr Zeit gewinnen wollt, weil ihr seht, dass die Sache von mir fest beschlossen* ist:", footnotes: ["w. verkündet"] },
      { number: 9, text: "Wenn ihr mir den Traum nicht mitteilt, *bleibt es bei eurer Verurteilung*. Denn ihr habt euch verabredet, lügnerische und trügerische Rede vor mir zu reden, bis die Zeit sich ändert. Darum sagt mir den Traum! Und ich werde wissen, dass ihr mir seine Deutung kundtun könnt.", footnotes: ["w. ist der Befehl über euch einer; d. h. das Todesurteil", "w. ist der Befehl über euch einer; d. h. das Todesurteil"] },
      { number: 10, text: "Die Sterndeuter* antworteten vor dem König und sagten: Es gibt keinen Menschen auf der <ganzen> Erde*, der die Sache des Königs kundtun könnte, weil kein großer und mächtiger König jemals eine Sache wie diese von irgendeinem Wahrsagepriester oder Beschwörer oder Sterndeuter* verlangt hat.", footnotes: ["hebr. Chaldäer. — Der Volksname Chaldäer wurde eine Berufsbezeichnung für Astrologen.", "w. dem Trockenen", "w. dem Trockenen"] },
      { number: 11, text: "Denn die Sache, die der König verlangt, ist <zu> schwer; und es gibt keinen anderen, der sie vor dem König kundtun könnte, als nur die Götter, deren Wohnung <aber> nicht bei den Sterblichen* ist*.", footnotes: ["w. nicht bei Fleisch", "℘ Kap. 4,4; 1Mo 41,8.24; Jes 47,12-14"] },
      { number: 12, text: "Darüber wurde der König zornig und ergrimmte sehr, und er befahl, alle Weisen von Babel umzubringen." },
      { number: 13, text: "Und es erging der Befehl: »Die Weisen sollen getötet werden!« Und man suchte <auch> Daniel und seine Gefährten, um <sie> zu töten." },
      { number: 14, text: "Da machte Daniel dem Arjoch, dem obersten Leibwächter des Königs, der ausgezogen war, um die Weisen von Babel zu töten, einen klugen und verständigen Einwand*,", footnotes: ["w. Darauf erwiderte Daniel dem Arjoch . . . <mit> Rat und Einsicht"] },
      { number: 15, text: "indem er dem Arjoch, dem Bevollmächtigten des Königs, antwortete und sagte: Warum der strenge Befehl vom König? Da teilte Arjoch dem Daniel die Sache mit." },
      { number: 16, text: "Und Daniel ging hinein und erbat sich vom König, dass er ihm eine Frist gewähre, dem König die Deutung kundzutun*.", footnotes: ["℘ Spr 16,14"] },
      { number: 17, text: "Darauf ging Daniel in sein Haus; und er teilte seinen Gefährten Hananja, Mischaël und Asarja* die Sache mit,", footnotes: ["℘ Kap. 1,6.19"] },
      { number: 18, text: "damit sie den Gott des Himmels um Erbarmen bitten sollten wegen dieses Geheimnisses, damit Daniel und seine Gefährten nicht mit den übrigen Weisen von Babel umkämen." },
      { number: 19, text: "Darauf wurde dem Daniel in einer Nachtvision das Geheimnis offenbart*. Da pries Daniel den Gott des Himmels.", footnotes: ["℘ Kap. 1,17; 4Mo 12,6"] },
      { number: 20, text: "Daniel fing an und sprach: Gepriesen sei der Name Gottes von Ewigkeit zu Ewigkeit*! Denn Weisheit und Macht, sie sind sein*.", footnotes: ["℘ 1Chr 29,10; Neh 9,5; Ps 41,14; 113,2", "℘ Hi 12,13; Ps 147,5; Röm 11,33"] },
      { number: 21, text: "Er ändert Zeiten und Fristen, er setzt Könige ab und setzt Könige ein*; er gibt den Weisen Weisheit und Erkenntnis den Einsichtigen*;", footnotes: ["℘ Kap. 4,14; Hi 12,18", "℘ Spr 2,6; Jak 1,5"] },
      { number: 22, text: "er offenbart das Tiefe und das Verborgene*; er weiß, was in der Finsternis ist, und bei ihm wohnt das Licht*.", footnotes: ["℘ 5Mo 29,28; Hi 12,22; Pred 8,1", "℘ Ps 139,12; 1Tim 6,16"] },
      { number: 23, text: "Dich, Gott meiner Väter, lobe und preise ich, dass du mir Weisheit und Kraft gegeben und mich jetzt hast wissen lassen, was wir von dir erbeten haben; denn du hast uns die Sache des Königs wissen lassen*.", footnotes: ["℘ Jer 33,3"] },
      { number: 24, text: "Deshalb ging Daniel zu Arjoch hinein, den der König eingesetzt hatte, die Weisen von Babel umzubringen. Er ging hin und sprach zu ihm so: Was die Weisen von Babel betrifft, bringe <sie> nicht um! Führe mich <aber> vor den König, damit ich dem König die Deutung kundtue!" },
      { number: 25, text: "Da führte Arjoch den Daniel schnell vor den König* und sprach zu ihm so: Ich habe einen Mann unter den Weggeführten* von Juda* gefunden, der dem König die Deutung mitteilen will.", footnotes: ["℘ 1Mo 41,14", "w. unter den Söhnen der Wegführung", "℘ Kap. 5,13"] },
      { number: 26, text: "Der König fing an und sprach zu Daniel, dessen Name Beltschazar war: Bist du imstande, mir den Traum, den ich gesehen habe, und seine Deutung mitzuteilen?" },
      { number: 27, text: "Daniel antwortete vor dem König und sprach: Das Geheimnis, das der König verlangt, können Weise, Beschwörer, Wahrsagepriester und Zeichendeuter dem König nicht kundtun*.", footnotes: ["℘ Kap. 5,8"] },
      { number: 28, text: "Aber es gibt einen Gott im Himmel, der Geheimnisse offenbart*; und er lässt den König Nebukadnezar wissen, was am Ende der Tage geschehen wird*. Dein Traum und die Visionen deines Hauptes auf deinem Lager waren diese:", footnotes: ["℘ 1Mo 40,8", "℘ Kap. 10,14; Offb 1,1"] },
      { number: 29, text: "Dir, König, stiegen auf deinem Lager Gedanken auf, was nach diesem geschehen werde. Und der die Geheimnisse offenbart, <er> hat dich wissen lassen, was geschehen wird." },
      { number: 30, text: "Mir aber ist nicht durch Weisheit, die in mir mehr als in allen Lebenden wäre, dieses Geheimnis offenbart worden*, sondern deshalb, damit man den König die Deutung wissen lasse und du die Gedanken deines Herzens erfährst.", footnotes: ["℘ Apg 3,12"] },
      { number: 31, text: "*Du, König, schautest: Und siehe, ein großes Bild*! Dieses Bild war gewaltig und sein Glanz außergewöhnlich; es stand vor dir, und sein Aussehen war furchtbar.", footnotes: ["℘ V. 31-36: V. 37-45", "d. h. ein Standbild"] },
      { number: 32, text: "Dieses Bild, sein Haupt war aus feinem Gold, seine Brust und seine Arme aus Silber, sein Bauch* und seine Lenden aus Bronze,", footnotes: ["w. seine Eingeweide"] },
      { number: 33, text: "seine Schenkel aus Eisen, seine Füße teils aus Eisen und teils aus Ton." },
      { number: 34, text: "Du schautest, bis ein Stein losbrach, <und zwar> nicht durch Hände, und das Bild an seinen Füßen aus Eisen und Ton traf und sie zermalmte." },
      { number: 35, text: "Da wurden zugleich das Eisen, der Ton, die Bronze, das Silber und das Gold zermalmt, und sie wurden wie Spreu aus den Sommertennen; und der Wind führte sie fort, und es war keinerlei Spur mehr von ihnen zu finden. Und der Stein, der das Bild zerschlagen hatte, wurde zu einem großen Berg und erfüllte die ganze Erde." },
      { number: 36, text: "*Das ist der Traum. Und seine Deutung wollen wir vor dem König ansagen*:", footnotes: ["℘ V. 37-45: V. 31-36", "℘ 1Mo 40,12.18"] },
      { number: 37, text: "Du, König, du König der Könige*, dem der Gott des Himmels die Königsherrschaft, die Macht und die Stärke und die Ehre gegeben hat*", footnotes: ["℘ Hes 26,7", "℘ Kap. 5,18; Esr 1,2"] },
      { number: 38, text: "— und überall, wo Menschenkinder, Tiere des Feldes und Vögel des Himmels wohnen, hat er <sie> in deine Hand gegeben* und dich zum Herrscher über sie alle gesetzt* —, du bist das Haupt aus Gold.", footnotes: ["o. wo Menschenkinder wohnen, hat er die Tiere des Feldes und die Vögel des Himmels in deine Hand gegeben", "℘ Kap. 4,18.19; 7,4; Jer 27,5-7"] },
      { number: 39, text: "Und nach dir wird ein anderes Königreich erstehen, geringer als du*, und ein anderes, drittes Königreich, aus Bronze, das über die ganze Erde herrschen wird*.", footnotes: ["℘ Kap. 5,28; 7,5.6", "℘ Kap. 8,20.21"] },
      { number: 40, text: "Und ein viertes Königreich wird stark sein wie Eisen, deshalb weil das Eisen alles zermalmt und zerschmettert; wie das Eisen, das <alles> zertrümmert, wird es all jene zermalmen und zertrümmern*.", footnotes: ["℘ Kap. 7,7.23"] },
      { number: 41, text: "Und dass du die Füße und die Zehen teils aus Töpferton und teils aus Eisen gesehen hast: <Das> wird ein geteiltes Königreich sein; aber von der Festigkeit des Eisens wird <etwas> in ihm sein, weil du das Eisen mit lehmigem Ton vermischt gesehen hast." },
      { number: 42, text: "Und die Zehen der Füße, teils aus Eisen und teils aus Ton: Zum Teil wird das Königreich stark sein, und zum Teil* wird es zerbrechlich sein.", footnotes: ["o. an einem Ende wird das Königreich stark sein, und in einem Teil"] },
      { number: 43, text: "Dass du das Eisen mit lehmigem Ton vermischt gesehen hast: Sie werden sich durch Heiraten untereinander* vermischen, aber sie werden nicht aneinander haften, so wie sich Eisen mit Ton nicht mischen lässt.", footnotes: ["w. durch den Samen der Menschen"] },
      { number: 44, text: "Und in den Tagen dieser Könige wird der Gott des Himmels ein Königreich aufrichten*, das ewig nicht zerstört werden wird. Und das Königreich wird keinem anderen Volk überlassen werden; es wird all jene Königreiche zermalmen und vernichten, selbst aber wird es ewig bestehen*:", footnotes: ["℘ Ps 2,6-8; Offb 11,15", "℘ Kap. 3,33; 6,27; 7,13.14; 2Sam 7,13; Lk 1,33; Hebr 12,27"] },
      { number: 45, text: "Wie* du gesehen hast, dass von dem Berg ein Stein losbrach*, <und zwar> nicht durch Hände, und das Eisen, die Bronze, den Ton, das Silber und das Gold zermalmte*. Ein großer Gott lässt den König wissen, was nach diesem geschehen wird*; und der Traum ist zuverlässig und seine Deutung zutreffend.", footnotes: ["w. weil", "℘ Jes 28,16; Mt 21,44", "℘ Ps 2,9; Hag 2,22; Lk 20,18; Offb 19,15", "℘ 1Mo 41,28"] },
      { number: 46, text: "Da fiel der König Nebukadnezar auf sein Angesicht und warf sich vor Daniel nieder*. Und er befahl, ihm Opfer und Räucherwerk* darzubringen*.", footnotes: ["℘ Apg 10,25", "w. Wohlgeruch", "℘ Apg 14,13"] },
      { number: 47, text: "Der König antwortete Daniel und sprach: In Wahrheit, euer Gott, er ist Gott der Götter* und Herr der Könige* und offenbart Geheimnisse, da du dieses Geheimnis offenbaren konntest.", footnotes: ["℘ 5Mo 10,17; 2Kö 5,15; Ps 96,4; 1Tim 6,15", "℘ Offb 17,14"] },
      { number: 48, text: "Daraufhin machte der König den Daniel groß und gab ihm viele große Geschenke*, und er setzte ihn als Herrscher über die ganze Provinz Babel ein und zum Obervorsteher über alle Weisen von Babel*.", footnotes: ["℘ Kap. 5,7.16", "℘ V. 6; Kap. 4,6; 5,11; 1Mo 41,41"] },
      { number: 49, text: "Und Daniel erbat vom König, dass er Schadrach, Meschach und Abed-Nego* über die Verwaltung der Provinz Babel einsetze*. Aber Daniel blieb am Hof des Königs*.", footnotes: ["℘ Kap. 3,12", "℘ Kap. 3,1.30", "w. war im Tor des Königs; vgl. Est 3,2\n℘ Est 3,2"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Der König Nebukadnezar machte ein Bild* aus Gold: seine Höhe <betrug> sechzig Ellen, seine Breite sechs Ellen. Er stellte es auf in der Ebene Dura, in der Provinz Babel*.", heading: "Die drei Männer im Feuerofen", footnotes: ["d. i. ein Standbild, eine Statue", "℘ Kap. 2,49"] },
      { number: 2, text: "Und der König Nebukadnezar sandte <Boten> aus, um die Satrapen*, die Statthalter und die Verwalter*, die Berater, die Schatzmeister, die Richter, die Polizeibefehlshaber und alle Oberbeamten der Provinzen zu versammeln, damit sie zur Einweihung des Bildes kämen, das der König Nebukadnezar aufgestellt hatte.", footnotes: ["Ein Satrap ist der Statthalter einer Provinz.", "Das sind Stellvertreter der Statthalter."] },
      { number: 3, text: "Daraufhin versammelten sich die Satrapen*, die Statthalter und die Verwalter*, die Berater, die Schatzmeister, die Richter, die Polizeibefehlshaber und alle Oberbeamten der Provinzen zur Einweihung des Bildes, das der König Nebukadnezar aufgestellt hatte; und sie standen vor dem Bild, das Nebukadnezar aufgestellt hatte.", footnotes: ["Ein Satrap ist der Statthalter einer Provinz.", "Das sind Stellvertreter der Statthalter."] },
      { number: 4, text: "Und der Herold rief laut*: Euch wird befohlen, ihr Völker, Nationen und Sprachen:", footnotes: ["w. mit Kraft"] },
      { number: 5, text: "Sobald ihr den Klang des Horns, der Rohrpfeife, der Zither, der Harfe, der Laute, des Dudelsacks und alle Arten von Musik* hört, sollt ihr niederfallen und euch vor dem goldenen Bild niederwerfen, das der König Nebukadnezar aufgestellt hat*.", footnotes: ["o. Saitenspiel", "℘ Ps 115,4-8"] },
      { number: 6, text: "Wer aber nicht niederfällt und anbetet*, der soll sofort in den brennenden Feuerofen geworfen werden*.", footnotes: ["w. sich nicht niederwirft", "℘ Jer 29,22; Offb 13,15"] },
      { number: 7, text: "Deshalb, sobald alle Völker den Klang des Horns, der Rohrpfeife, der Zither, der Harfe, der Laute und alle Arten von Musik* hörten, fielen alle Völker, Nationen und Sprachen nieder, indem sie sich vor dem goldenen Bild niederwarfen, das der König Nebukadnezar aufgestellt hatte.", footnotes: ["o. Saitenspiel"] },
      { number: 8, text: "Deshalb traten zur selben Zeit <einige> Männer heran, nämlich Sterndeuter*, die die Juden verklagten.", footnotes: ["w. chaldäische Männer; s. Anm. zu Kap. 2,2"] },
      { number: 9, text: "Sie fingen an und sagten zum König Nebukadnezar: König, lebe ewig!*", footnotes: ["℘ Kap. 2,4"] },
      { number: 10, text: "Du, König, hast den Befehl gegeben, dass jedermann, der den Klang des Horns, der Rohrpfeife, der Zither, der Harfe, der Laute und des Dudelsacks und alle Arten von Musik* hört, niederfallen und das goldene Bild anbeten soll;", footnotes: ["o. Saitenspiel"] },
      { number: 11, text: "und wer nicht niederfällt und anbetet*, der sollte in den brennenden Feuerofen geworfen werden*.", footnotes: ["w. sich nicht niederwirft", "℘ Kap. 6,13"] },
      { number: 12, text: "Nun sind jüdische Männer hier, die du zur Verwaltung der Provinz Babel eingesetzt hast: Schadrach, Meschach und Abed-Nego*. Diese Männer, König, schenken dir keine Beachtung; deinen Göttern dienen sie nicht, und vor dem goldenen Bild, das du aufgestellt hast, werfen sie sich nicht nieder*.", footnotes: ["℘ Kap. 2,49", "℘ Kap. 6,14"] },
      { number: 13, text: "Da befahl Nebukadnezar voller Zorn und Wut, Schadrach, Meschach und Abed-Nego herzubringen. Da wurden diese Männer vor den König gebracht*.", footnotes: ["℘ Mt 10,18"] },
      { number: 14, text: "Nebukadnezar fing an und sagte zu ihnen: Ist es Absicht*, Schadrach, Meschach und Abed-Nego, dass ihr meinen Göttern nicht dient und euch vor dem goldenen Bild, das ich aufgestellt habe, nicht niederwerft?", footnotes: ["o. Ist es wahr"] },
      { number: 15, text: "Nun, wenn ihr bereit seid, zur Zeit, da ihr den Klang des Horns, der Rohrpfeife, der Zither, der Harfe, der Laute und des Dudelsacks und alle Arten von Musik* hören werdet, hinzufallen und euch vor dem Bild niederzuwerfen, das ich gemacht habe<, so ist es gut>. Wenn ihr euch aber nicht niederwerft, dann werdet ihr sofort in den brennenden Feuerofen geworfen. Und wer ist der Gott, der euch aus meiner Hand retten könnte?*", footnotes: ["o. Saitenspiel", "℘ 2Kö 18,35"] },
      { number: 16, text: "Schadrach, Meschach und Abed-Nego antworteten und sagten zum König: Nebukadnezar, wir haben es nicht nötig, dir ein Wort darauf zu erwidern." },
      { number: 17, text: "Ob unser Gott, dem wir dienen, uns retten kann — sowohl aus dem brennenden Feuerofen als auch aus deiner Hand, König, wird er <uns> retten* —", footnotes: ["℘ Ps 37,39.40; Mt 10,28; 2Petr 2,9"] },
      { number: 18, text: "oder ob nicht: Es sei dir <jedenfalls> kund, König, dass wir deinen Göttern nicht dienen und uns vor dem goldenen Bild, das du aufgestellt hast, nicht niederwerfen werden*.", footnotes: ["℘ 2Mo 20,3-5; Apg 4,19"] },
      { number: 19, text: "Da wurde Nebukadnezar voller Wut*, und der Ausdruck seines Gesichts änderte sich gegenüber* Schadrach, Meschach und Abed-Nego. Er begann und befahl, den Ofen siebenmal mehr zu heizen, als es ausreichend war*.", footnotes: ["℘ Est 3,5; Apg 5,33", "o. wegen", "w. als es <für nötig> angesehen war, ihn zu heizen"] },
      { number: 20, text: "Dann befahl er Männern, den stärksten Männern in seinem Heer, Schadrach, Meschach und Abed-Nego zu binden, um sie in den brennenden Feuerofen zu werfen." },
      { number: 21, text: "Daraufhin wurden diese Männer in ihren Mänteln*, Röcken und Mützen und ihren <sonstigen> Kleidern gebunden und in den brennenden Feuerofen geworfen.", footnotes: ["o. Hosen"] },
      { number: 22, text: "Darum, weil das Wort des Königs <so> streng und der Ofen außergewöhnlich geheizt war, tötete die Flamme des Feuers jene Männer, die Schadrach, Meschach und Abed-Nego hinaufbrachten." },
      { number: 23, text: "Und diese drei Männer, Schadrach, Meschach und Abed-Nego, fielen gebunden in den brennenden Feuerofen." },
      { number: 24, text: "Da erschrak der König Nebukadnezar und erhob sich schnell. Er begann und sagte zu seinen Staatsräten: Haben wir nicht drei Männer gebunden ins Feuer geworfen? Sie antworteten und sagten zum König: Gewiss, König!" },
      { number: 25, text: "Er antwortete und sprach: Siehe, ich sehe vier Männer frei umhergehen mitten im Feuer, und keine Verletzung ist an ihnen*; und das Aussehen des Vierten gleicht dem eines Göttersohnes.", footnotes: ["℘ Jes 43,2; Hebr 11,34"] },
      { number: 26, text: "Da trat Nebukadnezar an die Öffnung des brennenden Feuerofens, begann und sagte: Schadrach, Meschach und Abed-Nego, ihr Knechte des höchsten Gottes*, geht heraus und kommt her! Da gingen Schadrach, Meschach und Abed-Nego aus dem Feuer heraus*.", footnotes: ["℘ Kap. 6,21", "℘ Ps 66,12"] },
      { number: 27, text: "Und es versammelten sich die Satrapen*, die Statthalter, die Verwalter* und die Staatsräte des Königs; sie betrachteten diese Männer, über deren Leib das Feuer keine Macht gehabt hatte: das Haar ihres Hauptes war nicht versengt, und ihre Mäntel* waren nicht verändert, nicht einmal Brandgeruch war an sie gekommen.", footnotes: ["Ein Satrap ist der Statthalter einer Provinz.", "Das sind Stellvertreter der Statthalter.", "o. Hosen"] },
      { number: 28, text: "Nebukadnezar begann und sagte: Gepriesen sei der Gott Schadrachs, Meschachs und Abed-Negos, der seinen Engel gesandt* und seine Knechte gerettet hat, die sich auf ihn verließen* und das Wort des Königs übertraten und ihren Leib dahingaben*, damit sie keinem Gott dienen oder ihn anbeten müssten als nur ihren Gott*!", footnotes: ["℘ Kap. 6,23; Apg 12,11", "℘ Ps 22,5; 34,8.9", "℘ Offb 12,11", "w. sich vor ihm niederwerfen müssten als nur vor ihrem Gott"] },
      { number: 29, text: "So ergeht nun von mir der Befehl, der jedes Volk, jede Nation und Sprache <betrifft>: Wer über den Gott Schadrachs, Meschachs und Abed-Negos etwas Verächtliches sagt, soll in Stücke gehauen werden, und sein Haus soll zu einem Misthaufen gemacht werden*. Denn es gibt keinen anderen Gott, der so retten kann*.", footnotes: ["℘ Kap. 2,5", "℘ Kap. 6,28"] },
      { number: 30, text: "Sodann beförderte* der König Schadrach, Meschach und Abed-Nego in der Provinz Babel*.", footnotes: ["o. beließ; o. setzte . . . wieder ein", "℘ Kap. 2,49"] },
      { number: 31, text: "Der König Nebukadnezar an alle Völker, Nationen und Sprachen, die auf der ganzen Erde wohnen: Euer Friede werde groß*!", heading: "Nebukadnezars Traum vom umgehauenen Baum", footnotes: ["℘ Kap. 6,26; 2Petr 1,2"] },
      { number: 32, text: "Es schien mir gut, die Zeichen und Wunder kundzutun, die der höchste Gott an mir getan hat*.", footnotes: ["℘ Ps 66,16; Lk 8,39"] },
      { number: 33, text: "Wie groß sind seine Zeichen und wie mächtig seine Wunder*! Sein Reich ist ein ewiges Reich*, und seine Herrschaft <währt> von Geschlecht zu Geschlecht!* —", footnotes: ["℘ Kap. 6,28", "o. Sein Königreich ist das Königreich der Ewigkeit", "℘ Kap. 2,44; 4,31; 2Mo 15,18; Ps 145,13; Jer 10,10"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Ich, Nebukadnezar, war sorglos in meinem Haus und glücklich in meinem Palast." },
      { number: 2, text: "Ich sah einen Traum, und er erschreckte mich; und Traumgestalten auf meinem Lager und Visionen, die ich gesehen hatte*, ängstigten mich*.", footnotes: ["w. die Gesichte meines Hauptes", "℘ Kap. 2,1; Hi 7,14; Ps 65,9"] },
      { number: 3, text: "So erging von mir der Befehl, alle Weisen von Babel vor mich zu führen, damit sie mir die Deutung des Traums mitteilten*.", footnotes: ["℘ Kap. 2,2"] },
      { number: 4, text: "Daraufhin kamen die Wahrsagepriester, die Beschwörer, die Sterndeuter* und die Zeichendeuter herbei; und ich trug ihnen den Traum vor, aber sie teilten mir seine Deutung nicht mit*.", footnotes: ["aram. Chaldäer; s. Anm. Kap. 2,2", "℘ Kap. 2,11; 5,8"] },
      { number: 5, text: "Und zuletzt trat Daniel vor mich, dessen Name Beltschazar ist*, nach dem Namen meines Gottes, und in dem der Geist der heiligen Götter ist*. Und ich trug ihm den Traum vor:", footnotes: ["℘ Kap. 1,7", "℘ V. 15; Kap. 5,11.14"] },
      { number: 6, text: "Beltschazar, du Oberster der Wahrsagepriester*, weil ich weiß, dass der Geist der heiligen Götter in dir ist* und dass dir kein Geheimnis zu schwer ist, so sage mir die Visionen meines Traumes, den ich gesehen habe, und seine Deutung*!", footnotes: ["℘ Kap. 2,48", "℘ V. 15; Kap. 5,11.14", "℘ Kap. 1,17"] },
      { number: 7, text: "Was nun die Visionen, die ich auf meinem Lager hatte*, betrifft, so schaute ich: Und siehe, ein Baum <stand> in der Mitte der Erde, und seine Höhe war gewaltig*.", footnotes: ["w. die Gesichte meines Hauptes auf meinem Lager", "℘ Ps 37,35; Hes 31,3"] },
      { number: 8, text: "Der Baum wurde groß und stark, und seine Höhe reichte bis an den Himmel, und er wurde gesehen bis ans Ende der ganzen Erde." },
      { number: 9, text: "Sein Laub war schön und seine Frucht zahlreich, und es war Nahrung an ihm für alle. Die Tiere des Feldes fanden Schatten unter ihm, und die Vögel des Himmels wohnten in seinen Zweigen, und alles Fleisch nährte sich von ihm*.", footnotes: ["℘ Hes 17,23"] },
      { number: 10, text: "Ich schaute in den Visionen, die ich auf meinem Lager hatte*, und siehe, ein Wächter* und Heiliger* stieg vom Himmel herab.", footnotes: ["w. in den Gesichten meines Hauptes auf meinem Lager", "o. Engel", "℘ Kap. 8,13"] },
      { number: 11, text: "Er rief laut*, und so sprach er: Haut den Baum um* und schlagt seine Äste ab! Streift sein Laub ab und streut seine Frucht umher! Fliehen sollen die Tiere unter ihm weg und die Vögel aus seinen Ästen*!", footnotes: ["w. mit Kraft", "℘ Lk 13,7", "℘ Hes 31,12; Mt 13,32"] },
      { number: 12, text: "Doch seinen Wurzelstock lasst in der Erde, und zwar in einer Fessel aus Eisen und Bronze im Grün des Feldes! Vom Tau des Himmels mag er benetzt werden*, und mit den Tieren soll er teilhaben am Gras der Erde!*", footnotes: ["℘ Hi 14,7-9", "℘ Hi 12,24"] },
      { number: 13, text: "Sein menschliches Herz soll verwandelt und das Herz eines Tieres ihm gegeben werden! Und sieben Jahre* sollen über ihm vergehen!", footnotes: ["o. Zeiten"] },
      { number: 14, text: "Durch den Beschluss der Wächter* ist diese Botschaft <zustande gekommen>, und ein Spruch der Heiligen ist diese Sache, damit die Lebenden erkennen, dass der Höchste Macht hat über das Königtum der Menschen und es verleiht, wem er will*, und den Niedrigsten der Menschen darüber einsetzt.", footnotes: ["o. Engel", "℘ V. 29; Kap. 2,21; 5,21; Jer 27,5"] },
      { number: 15, text: "Diesen Traum habe ich, der König Nebukadnezar, gesehen. Und du, Beltschazar, sage seine Deutung, da alle Weisen meines Königreichs mir die Deutung nicht mitteilen können! Du aber kannst es, weil der Geist der heiligen Götter in dir ist*.", footnotes: ["℘ V. 5.6"] },
      { number: 16, text: "Da war Daniel, dessen Name Beltschazar ist, eine Zeit lang <vor Entsetzen wie> betäubt, und seine Gedanken erschreckten ihn*. Der König fing an und sagte: Beltschazar, der Traum und seine Deutung mögen dich nicht erschrecken! Beltschazar antwortete und sprach: Mein Herr, der Traum gelte deinen Hassern und seine Deutung deinen Feinden*!", footnotes: ["℘ Kap. 7,28", "℘ 2Sam 18,32"] },
      { number: 17, text: "Der Baum, den du gesehen hast, der groß und stark war und dessen Höhe an den Himmel reichte und der über die ganze Erde hin zu sehen war" },
      { number: 18, text: "und dessen Laub schön und dessen Frucht zahlreich und an dem Nahrung für alle war, unter dem die Tiere des Feldes wohnten und in dessen Ästen die Vögel des Himmels sich aufhielten:" },
      { number: 19, text: "Das bist du, König, der du groß und stark geworden bist; und deine Größe nahm zu und reichte bis an den Himmel und deine Herrschaft bis ans Ende der Erde*.", footnotes: ["℘ Kap. 2,37.38; 5,18.19"] },
      { number: 20, text: "Und dass der König einen Wächter* und Heiligen vom Himmel herabsteigen sah, der sprach: »Haut den Baum um und zerstört ihn! Doch seinen Wurzelstock lasst in der Erde, und zwar in einer Fessel aus Eisen und Bronze im Grün des Feldes! Und vom Tau des Himmels mag er benetzt werden, und bei den Tieren des Feldes soll er sein Teil haben, bis sieben Jahre* über ihn hingegangen sind!« —", footnotes: ["o. Engel", "o. Zeiten"] },
      { number: 21, text: "dies ist die Deutung, König. Und dies der Beschluss des Höchsten, der über meinen Herrn, den König, kommen wird:" },
      { number: 22, text: "Man wird dich von den Menschen ausstoßen, und bei den Tieren des Feldes wird deine Wohnung sein. Man wird dir Gras zu essen geben wie den Rindern, und vom Tau des Himmels lässt man dich benetzen. Und es werden sieben Jahre* über dir vergehen, bis du erkennst, dass der Höchste über das Königtum der Menschen herrscht* und es verleiht, wem er will*.", footnotes: ["o. Zeiten", "℘ Ps 83,19", "℘ V. 29; Kap. 2,21; 5,21; Jer 27,5"] },
      { number: 23, text: "Und dass man gesagt hat, man solle den Wurzelstock des Baumes übrig lassen: Dein Königtum soll dir <erhalten> bleiben, sobald du erkennst, dass der Himmel herrscht." },
      { number: 24, text: "Darum, König, lass dir meinen Rat gefallen und brich mit deinen Sünden durch Gerechtigkeit und mit deinen Vergehen durch Barmherzigkeit gegen Elende, wenn dein Wohlergehen von Dauer sein soll!*", footnotes: ["℘ Spr 16,6; 20,28"] },
      { number: 25, text: "All das kam über den König Nebukadnezar." },
      { number: 26, text: "Nach Ablauf von zwölf Monaten <nämlich>, als er auf dem königlichen Palast in Babel auf und ab ging," },
      { number: 27, text: "begann der König und sagte: Ist das nicht das große Babel*, das ich durch die Stärke meiner Macht und zur Ehre meiner Herrlichkeit zum königlichen Wohnsitz erbaut habe*?", footnotes: ["℘ Offb 14,8", "℘ 1Mo 11,4; 5Mo 8,17; 32,27; Jes 10,13; 47,8; Hes 29,3; Zef 2,15"] },
      { number: 28, text: "Noch war das Wort im Mund des Königs, da kam eine Stimme aus dem Himmel*: Dir, König Nebukadnezar, wird gesagt: Das Königtum ist von dir gewichen*!", footnotes: ["w. fiel eine Stimme . . . herab", "℘ Kap. 5,20"] },
      { number: 29, text: "Und man wird dich von den Menschen ausstoßen, und bei den Tieren des Feldes wird deine Wohnung sein; man wird dir Gras zu essen geben wie den Rindern. Und es werden sieben Jahre über dir vergehen, bis du erkennst, dass der Höchste Macht hat über das Königtum der Menschen und es verleiht, wem er will*.", footnotes: ["℘ V. 14.22; Röm 13,1"] },
      { number: 30, text: "Zu derselben Stunde wurde das Wort an Nebukadnezar erfüllt*: Er wurde von den Menschen ausgestoßen und aß Gras wie die Rinder, und sein Leib wurde benetzt vom Tau des Himmels, bis sein Haar wie Adlerfedern wuchs und seine Nägel wie Vogelkrallen*.", footnotes: ["℘ Spr 16,18; Apg 12,23", "℘ Spr 11,2"] },
      { number: 31, text: "Und am Ende der Tage erhob ich, Nebukadnezar, meine Augen zum Himmel, und mein Verstand* kehrte zu mir zurück. Und ich pries den Höchsten*, und ich rühmte und verherrlichte den ewig Lebenden*, dessen Herrschaft eine ewige Herrschaft ist und dessen Reich* von Geschlecht zu Geschlecht <währt>*.", footnotes: ["w. meine Erkenntnis", "℘ 1Mo 14,18.19", "℘ Kap. 6,27; 12,7; 1Tim 6,16; Offb 4,9", "o. Königtum", "℘ Kap. 3,33; Ps 145,13"] },
      { number: 32, text: "Und alle Bewohner der Erde sind wie nichts gerechnet*, und nach seinem Willen verfährt er mit dem Heer des Himmels und den Bewohnern der Erde*. Und da ist niemand, der seiner Hand wehren und zu ihm sagen könnte: Was tust du?*", footnotes: ["℘ Jes 40,15-17", "℘ Ps 135,6", "℘ Hi 9,12; 42,2; Röm 9,10"] },
      { number: 33, text: "Zu derselben Zeit kehrte mein Verstand* zu mir zurück, und zur Ehre meines Königtums kehrten meine Herrlichkeit und mein Glanz zu mir zurück. Und meine Staatsräte und meine Gewaltigen suchten mich auf, und ich wurde wieder in mein Königtum eingesetzt, und außergewöhnliche Größe wurde mir hinzugefügt.", footnotes: ["w. meine Erkenntnis"] },
      { number: 34, text: "Nun rühme ich, Nebukadnezar, und erhebe und verherrliche den König des Himmels*, dessen Werke allesamt Wahrheit und dessen Wege Recht sind* und der die erniedrigen kann, die in Stolz einhergehen*.", footnotes: ["℘ 1Chr 29,10-13", "℘ Kap. 9,14; 5Mo 32,4; 2Sam 22,31; Ps 111,7", "℘ Jes 2,11.12; 13,11; Lk 1,51"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Der König Belsazar machte seinen tausend Gewaltigen ein großes Mahl*, und vor den Tausend trank er Wein*.", heading: "Belsazars Gastmahl und die geheimnisvolle Schrift", footnotes: ["℘ Est 1,3", "℘ Jes 21,5"] },
      { number: 2, text: "Belsazar befahl unter dem Einfluss* des Weins, die goldenen und die silbernen Gefäße herbeizubringen, die sein Vater Nebukadnezar aus dem Tempel in Jerusalem weggenommen hatte*, damit der König und seine Gewaltigen, seine Frauen und seine Nebenfrauen daraus tränken.", footnotes: ["w. unter dem Befehl", "℘ Kap. 1,2; 2Kö 24,13; 25,15; Esr 5,14"] },
      { number: 3, text: "Da brachte man die goldenen Gefäße, die man aus dem Tempel des Hauses Gottes in Jerusalem weggenommen hatte; und der König und seine Gewaltigen, seine Frauen und seine Nebenfrauen tranken daraus." },
      { number: 4, text: "Sie tranken Wein und rühmten die Götter aus Gold und Silber, aus Bronze, Eisen, Holz und Stein*.", footnotes: ["℘ Offb 9,20"] },
      { number: 5, text: "In demselben Augenblick kamen Finger einer Menschenhand hervor und schrieben dem Leuchter gegenüber auf den Kalk der Wand des königlichen Palastes; und der König sah die Hand*, die schrieb.", footnotes: ["w. die Fläche der Hand, o. die Knöchel der Hand"] },
      { number: 6, text: "Da veränderte sich die Gesichtsfarbe des Königs, und seine Gedanken erschreckten ihn, und seine Hüftgelenke erschlafften*, und seine Knie schlugen aneinander*.", footnotes: ["w. lösten sich", "℘ Jer 50,43"] },
      { number: 7, text: "Der König rief laut*, man solle die Beschwörer, die Sterndeuter* und die Zeichendeuter hereinbringen*. Und der König fing an und sagte zu den Weisen von Babel: Jeder, der diese Schrift lesen und mir ihre Deutung kundtun wird, der darf sich mit Purpur bekleiden, <dazu> mit einer goldenen Kette um seinen Hals, und er soll als Dritter im Königreich herrschen*.", footnotes: ["w. mit Kraft", "aram. Chaldäer; s. Anm. zu Kap. 2,2", "℘ Kap. 2,2", "℘ Kap. 2,48"] },
      { number: 8, text: "Da kamen alle Weisen des Königs herbei; aber sie konnten weder die Schrift lesen noch dem König ihre Deutung mitteilen*.", footnotes: ["℘ Kap. 2,27; 4,4"] },
      { number: 9, text: "Da geriet der König Belsazar in großen Schrecken, und seine Gesichtsfarbe an ihm veränderte sich; und seine Gewaltigen wurden bestürzt." },
      { number: 10, text: "Auf die Worte des Königs und seiner Gewaltigen hin trat die Königin* in das Haus des Trinkgelages. Die Königin begann und sagte: König, lebe ewig*! Lass deine Gedanken dich nicht schrecken, und deine Gesichtsfarbe verändere sich nicht!", footnotes: ["Mit dem Wort »Königin« kann sowohl die im alten Orient sehr einflussreiche Königin-Mutter als auch seine Lieblingsfrau gemeint sein.", "℘ Kap. 2,4"] },
      { number: 11, text: "Es gibt einen Mann in deinem Königreich, in dem der Geist der heiligen Götter ist*; und in den Tagen deines Vaters wurden Erleuchtung, Einsicht und Weisheit gleich der Weisheit der Götter bei ihm gefunden. Und der König Nebukadnezar, dein Vater, hat ihn zum Obersten der Wahrsagepriester, der Beschwörer, Sterndeuter* und Zeichendeuter eingesetzt*; dein Vater, König*!", footnotes: ["℘ Kap. 4,5.6.15; Hes 28,3", "aram. Chaldäer; s. Anm. zu Kap. 2,2", "℘ Kap. 2,48", "o. dein Vater, der König"] },
      { number: 12, text: "<Und zwar> deshalb, weil ein außergewöhnlicher Geist und Erkenntnis und Einsicht, Träume zu deuten, Rätsel zu erklären und Knoten zu lösen, bei ihm gefunden wurde*, bei Daniel, dem der König den Namen Beltschazar gegeben hat*. <Deshalb> lass jetzt Daniel rufen! Und er wird die Deutung kundtun.", footnotes: ["℘ Kap. 1,17; 6,4", "℘ Kap. 1,7"] },
      { number: 13, text: "Daraufhin wurde Daniel vor den König geführt. Der König fing an und sagte zu Daniel: Bist du Daniel, einer der Weggeführten* aus Juda, die der König, mein Vater, aus Juda hergebracht hat?*", footnotes: ["w. der Kinder der Wegführung", "℘ Kap. 1,6; 2,25"] },
      { number: 14, text: "Ich habe von dir gehört, dass der Geist der Götter in dir ist und dass Erleuchtung und Einsicht und außergewöhnliche Weisheit bei dir zu finden sind." },
      { number: 15, text: "Und nun sind die Weisen, die Beschwörer, vor mich geführt worden, damit sie diese Schrift lesen und mir ihre Deutung mitteilen sollten; aber sie können die Deutung der Sache nicht kundtun." },
      { number: 16, text: "Ich habe aber von dir gehört, dass du Deutungen geben* und Knoten lösen kannst. Nun, wenn du die Schrift lesen und mir ihre Deutung mitteilen kannst, darfst du dich mit Purpur bekleiden, <dazu> mit einer goldenen Kette um deinen Hals, und du sollst als Dritter im Königreich herrschen.*", footnotes: ["w. Deutungen deuten\n℘ 1Mo 41,15", "℘ V. 7; Kap. 2,6.48"] },
      { number: 17, text: "Da antwortete Daniel und sprach vor dem König: Deine Gaben mögen dir bleiben, und deine Geschenke gib einem anderen*! Jedoch werde ich die Schrift dem König lesen und ihm die Deutung mitteilen.", footnotes: ["℘ 2Kö 5,16"] },
      { number: 18, text: "Du, König! Der höchste Gott* hatte deinem Vater Nebukadnezar das Königtum und die Größe und die Majestät und die Herrlichkeit verliehen*.", footnotes: ["o. Gott, der Höchste", "℘ Kap. 2,37.38"] },
      { number: 19, text: "Und wegen der Größe, die er ihm verliehen hatte, zitterten und fürchteten sich vor ihm alle Völker, Nationen und Sprachen*. Er tötete, wen er wollte, er ließ leben, wen er wollte, er erhob, wen er wollte, und er erniedrigte, wen er wollte*.", footnotes: ["℘ Kap. 4,19", "℘ 2Kö 25,28; Pred 8,3"] },
      { number: 20, text: "Als aber sein Herz sich erhob* und sein Geist sich bis zur Vermessenheit verstockte, wurde er vom Thron seines Königtums gestürzt, und man nahm ihm seine Majestät*.", footnotes: ["℘ 2Chr 32,25; Hes 31,10", "℘ Kap. 4,26-30"] },
      { number: 21, text: "Und er wurde von den Menschenkindern ausgestoßen, und sein Herz wurde dem der Tiere gleich, und seine Wohnung war bei den Wildeseln. Man gab ihm Gras zu essen wie den Rindern, und sein Leib wurde vom Tau des Himmels benetzt* — bis er erkannte, dass der höchste Gott* Macht hat über das Königtum der Menschen und dass er darüber einsetzt, wen er will*.", footnotes: ["℘ Kap. 4,26-30", "o. Gott, der Höchste", "℘ Kap. 4,14.22"] },
      { number: 22, text: "Und du, Belsazar, sein Sohn, hast dein Herz nicht gedemütigt, obwohl du das alles gewusst hast*.", footnotes: ["℘ 2Chr 33,23"] },
      { number: 23, text: "Und du hast dich über den Herrn des Himmels erhoben*; und man hat die Gefäße seines Hauses vor dich gebracht, und du und deine Gewaltigen, deine Frauen und deine Nebenfrauen, ihr habt Wein daraus getrunken. Und du hast die Götter aus Silber und Gold, aus Bronze, Eisen, Holz und Stein gerühmt, die nicht sehen und nicht hören und nicht verstehen*. Aber den Gott, in dessen Hand dein Odem ist* und bei dem alle deine Wege sind*, hast du nicht geehrt*.", footnotes: ["℘ Kap. 8,11; Jes 37,23", "w. erkennen\n℘ Ps 115,4-8", "℘ Hi 12,10", "℘ Jer 10,23; Apg 17,25.28", "℘ 1Sam 17,26.36; Jer 50,28; Apg 12,23; Röm 1,21; Offb 9,20"] },
      { number: 24, text: "Da wurde von ihm diese Hand* gesandt und diese Schrift geschrieben.", footnotes: ["w. die Fläche der Hand, o. die Knöchel der Hand"] },
      { number: 25, text: "Und dies ist die Schrift, die geschrieben wurde: Mene, mene, tekel upharsin*.", footnotes: ["w. Mine, Mine, Schekel und Halbminen. — Zugleich aber sind diese Worte von Tätigkeitswörtern abgeleitet und können heißen: Gezählt, gezählt, gewogen und zerteilt. — Zudem klingt »pharsin« an den Namen »Perser« an."] },
      { number: 26, text: "Dies ist die Deutung des Wortes*: Mene — Gott hat dein Königtum gezählt und macht ihm ein Ende*.", footnotes: ["o. der Sache", "w. und hat es preisgegeben\n℘ Jer 25,12"] },
      { number: 27, text: "Tekel — du bist auf der Waage gewogen und zu leicht* befunden worden*.", footnotes: ["w. minderwertig", "℘ Spr 21,2; Nah 1,14"] },
      { number: 28, text: "Peres* — dein Königreich wird zerteilt* und den Medern und Persern gegeben*.", footnotes: ["d. i. die Einzahl zu pharsin", "w. abgerissen", "℘ Kap. 2,32.39; 8,20; 2Chr 36,23; Jes 13,17; 47,11; Jer 51,28"] },
      { number: 29, text: "Daraufhin gab Belsazar Befehl, und man bekleidete Daniel mit Purpur, <dazu> mit einer goldenen Kette um seinen Hals*; und man rief über ihn aus, dass er der Drittmächtigste* im Königreich sei*. —", footnotes: ["℘ 1Mo 41,42", "w. als Dritter mächtig", "℘ Est 10,3"] },
      { number: 30, text: "In derselben Nacht wurde Belsazar, der chaldäische König, getötet*.", footnotes: ["℘ Jer 51,31.39"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und Darius, der Meder*, übernahm die Königsherrschaft, als er 62 Jahre alt war.", heading: "Daniels Rettung aus der Löwengrube", footnotes: ["℘ Kap. 9,1; 11,1"] },
      { number: 2, text: "Es gefiel Darius, über das Königreich 120 Satrapen* einzusetzen, die im ganzen Königreich sein sollten,", footnotes: ["Ein Satrap ist der Statthalter einer Provinz."] },
      { number: 3, text: "und über sie drei Minister <zu setzen>, von denen einer Daniel war, denen jene Satrapen Rechenschaft geben sollten, damit der König keinen Schaden erlitte*.", footnotes: ["o. nicht belästigt würde\n℘ Esr 4,22"] },
      { number: 4, text: "Da übertraf dieser Daniel die Minister und die Satrapen, weil ein außergewöhnlicher Geist in ihm war*. Und der König beabsichtigte, ihn über das ganze Königreich einzusetzen.", footnotes: ["℘ Kap. 5,12; 1Mo 41,38"] },
      { number: 5, text: "Da suchten die Minister und die Satrapen einen Anklagegrund gegen Daniel in Bezug auf seine Amtsgeschäfte* zu finden*. Aber sie konnten keinerlei Anklagegrund und nichts Schlechtes finden, weil er treu war und keinerlei Nachlässigkeit* oder Schlechtes bei ihm zu finden waren*.", footnotes: ["w. vonseiten der Königsherrschaft", "℘ Ps 37,32", "o. Irrtum", "℘ 1Kor 4,2"] },
      { number: 6, text: "Da sagten diese Männer: Wir werden bei diesem Daniel keinen Anklagegrund finden, es sei denn, dass wir im Gesetz seines Gottes etwas gegen ihn finden." },
      { number: 7, text: "Daraufhin stürzten diese Minister und Satrapen zum König* und sprachen zu ihm so: König Darius, lebe ewig!*", footnotes: ["℘ Ps 59,5", "℘ V. 22; Kap. 2,4"] },
      { number: 8, text: "Alle Minister des Königreichs, die Statthalter und Satrapen, die Staatsräte und Verwalter* haben sich beraten, dass der König eine Verordnung erlassen und ein Verbot bestätigen solle, dass jeder, der innerhalb von dreißig Tagen an irgendeinen Gott oder Menschen eine Bitte richtet außer an dich, König, in die Löwengrube geworfen werden soll*.", footnotes: ["Das sind Stellvertreter der Statthalter.", "℘ Ps 94,21"] },
      { number: 9, text: "Nun, König, erlass das Verbot und lass ein Schriftstück ausfertigen*, das nicht geändert werden darf* nach dem Gesetz der Meder und Perser, das unaufhebbar ist*!", footnotes: ["w. schreibe eine Schrift", "℘ Est 1,19", "w. das nicht vergeht"] },
      { number: 10, text: "Daraufhin ließ der König Darius das Schriftstück und das Verbot ausfertigen*.", footnotes: ["w. Daraufhin schrieb der König Darius die Schrift und das Verbot"] },
      { number: 11, text: "Und als Daniel erfuhr, dass das Schriftstück ausgefertigt war*, ging er in sein Haus. Er hatte aber in seinem Obergemach* offene Fenster nach Jerusalem hin*; und dreimal am Tag kniete er auf seine Knie nieder, betete und pries vor seinem Gott, wie er <es auch> vorher getan hatte*.", footnotes: ["w. die Schrift geschrieben war", "℘ Mt 6,6", "℘ 1Kö 8,48; Ps 28,2; Jer 51,50", "℘ Ps 119,164; Apg 10,9"] },
      { number: 12, text: "Da stürzten jene Männer herbei und fanden Daniel betend und flehend vor seinem Gott." },
      { number: 13, text: "Darauf näherten sie sich dem König und sprachen vor <ihm> bezüglich des königlichen Verbotes: Hast du nicht ein Verbot ausfertigen lassen*, dass jedermann, der innerhalb von dreißig Tagen von irgendeinem Gott oder Menschen etwas erbittet außer von dir, König, in die Löwengrube geworfen werden sollte?* Der König antwortete und sprach: Das Wort ist unumstößlich nach dem Gesetz der Meder und Perser, das unaufhebbar ist*.", footnotes: ["w. geschrieben bzw. geschrieben hast", "℘ Kap. 3,8-11", "w. das nicht vergeht"] },
      { number: 14, text: "Darauf antworteten sie und sprachen vor dem König: Daniel, einer der Weggeführten* aus Juda*, schenkt weder dir, König, noch dem Verbot, das du hast ausfertigen lassen*, Beachtung; sondern er betet* dreimal am Tag*.", footnotes: ["w. einer der Kinder der Wegführung", "℘ Kap. 1,6", "w. geschrieben bzw. geschrieben hast", "w. er bittet seine Bitte", "℘ Kap. 3,12; Est 3,8"] },
      { number: 15, text: "Da missfiel es dem König, als er die Sache hörte, sehr*, und er sann darauf, Daniel zu retten*; und bis zum Untergang der Sonne bemühte er sich, ihn zu befreien.", footnotes: ["℘ Mk 6,26", "w. und auf Daniel richtete er das Herz, um ihn zu retten"] },
      { number: 16, text: "Da stürzten diese Männer zum König und sagten zum König: Wisse, König, dass die Meder und Perser ein Gesetz haben, wonach kein Verbot und keine Verordnung, die der König erlassen hat, abgeändert werden darf!" },
      { number: 17, text: "Dann befahl der König, und man brachte Daniel <herbei> und warf ihn in die Löwengrube*. Der König begann und sagte zu Daniel: Dein Gott, dem du ohne Unterlass dienst, er möge dich retten*!", footnotes: ["℘ Jer 38,5", "℘ Hi 5,19"] },
      { number: 18, text: "Und ein Stein wurde gebracht und auf die Öffnung der Grube gelegt*; und der König versiegelte ihn mit seinem Siegelring und mit den Siegelringen seiner Gewaltigen, damit die Sache mit Daniel nicht verändert würde*.", footnotes: ["℘ Kla 3,53", "℘ Mt 27,66"] },
      { number: 19, text: "Darauf ging der König in seinen Palast, und er übernachtete fastend und ließ keine Speise* zu sich hereinbringen; und sein Schlaf floh von ihm.", footnotes: ["Das hier stehende aram. Wort wird von manchen Übersetzern mit »Wohlgerüche«, von anderen mit »Konkubinen« wiedergegeben. Alte Belege weisen jedoch darauf hin, dass es sich um einen Speisebegriff handelt."] },
      { number: 20, text: "Dann stand der König bei der Morgenröte, sobald es hell wurde, auf und ging schnell zur Löwengrube." },
      { number: 21, text: "Und als er sich der Grube näherte, rief er mit trauriger* Stimme nach Daniel. Der König begann und sagte zu Daniel: Daniel, Knecht des lebendigen Gottes*, hat dein Gott, dem du ohne Unterlass dienst, dich von den Löwen retten können?", footnotes: ["o. ängstlicher", "℘ Kap. 3,26"] },
      { number: 22, text: "Da redete Daniel mit dem König: König, lebe ewig*!", footnotes: ["℘ V. 7"] },
      { number: 23, text: "Mein Gott hat seinen Engel gesandt*, und er hat den Rachen der Löwen verschlossen, so dass sie mich nicht verletzt haben*, weil vor ihm Unschuld an mir gefunden wurde*. Und auch vor dir, König, habe ich kein Verbrechen begangen*.", footnotes: ["℘ Kap. 3,28", "℘ Hebr 11,33", "℘ Ps 18,21", "℘ Apg 24,16"] },
      { number: 24, text: "Da freute sich der König sehr, und er befahl, Daniel aus der Grube herauszuholen. Und Daniel wurde aus der Grube herausgeholt; und keine Verletzung wurde an ihm gefunden, weil er auf seinen Gott vertraut hatte*.", footnotes: ["℘ Hebr 11,33"] },
      { number: 25, text: "Und der König befahl, und man brachte jene Männer, die Daniel verklagt hatten, und man warf sie in die Löwengrube*, sie, ihre Kinder und ihre Frauen. Und ehe sie noch am Boden der Grube angekommen waren, fielen die Löwen über sie her*, und sie zermalmten alle ihre Knochen*.", footnotes: ["℘ 5Mo 19,19; Spr 11,8", "w. herrschten . . . über sie", "℘ Est 7,10; Ps 7,15-17; 9,16.17"] },
      { number: 26, text: "Dann schrieb der König Darius an alle Völker, Nationen und Sprachen, die auf der ganzen Erde wohnten: Euer Friede sei groß!*", footnotes: ["℘ Kap. 3,31"] },
      { number: 27, text: "Von mir ergeht der Befehl, dass man in der ganzen Herrschaft meines Königreichs vor dem Gott Daniels zittere und sich fürchte! Denn er ist der lebendige Gott* und bleibt in Ewigkeit; und sein Königreich wird nicht zerstört werden, und seine Herrschaft <währt> bis ans Ende*.", footnotes: ["℘ Kap. 4,31; 1Sam 17,26; Jer 10,10; Apg 14,15", "℘ Kap. 2,44"] },
      { number: 28, text: "<Er,> der rettet und befreit und Zeichen und Wunder im Himmel und auf der Erde tut*, er hat Daniel aus der Gewalt der Löwen gerettet*.", footnotes: ["℘ Kap. 3,33; Ps 77,15; Jer 32,20", "℘ Kap. 3,29; 2Tim 4,17"] },
      { number: 29, text: "Und dieser Daniel stand in großem Ansehen* unter der Regierung des Darius und unter der Regierung des Kyrus, des Persers*.", footnotes: ["w. gedieh", "℘ Kap. 1,21"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "*Im ersten Jahr Belsazars, des Königs von Babel*, sah Daniel einen Traum und Visionen seines Hauptes auf seinem Lager*. Dann schrieb er den Traum auf, die Summe der Ereignisse* berichtete er*.", heading: "Daniels Vision von den vier Tieren und dem Menschensohn", footnotes: ["℘ V. 1-14: V. 15-28", "℘ Kap. 8,1", "℘ 4Mo 12,6", "o. Worte", "o. der Anfang der Worte lautete\n℘ Hab 2,2"] },
      { number: 2, text: "Daniel fing an und sprach: Ich schaute in meiner Vision in der Nacht, und siehe, die vier Winde des Himmels* wühlten das große Meer auf*.", footnotes: ["℘ Offb 7,1", "℘ Jes 17,12; Jer 51,42"] },
      { number: 3, text: "Und vier große Tiere stiegen aus dem Meer herauf, jedes verschieden vom anderen." },
      { number: 4, text: "Das erste war wie ein Löwe* und hatte Adlerflügel*; ich sah <hin>, bis seine Flügel ausgerissen wurden und es von der Erde aufgehoben und wie ein Mensch auf seine Füße gestellt und ihm das Herz eines Menschen gegeben wurde.", footnotes: ["℘ Kap. 2,38", "o. Geierflügel\n℘ 5Mo 28,49; Jer 4,7; 49,19.22"] },
      { number: 5, text: "Und siehe, ein anderes, ein zweites Tier, war einem Bären gleich. Und es war auf der einen Seite aufgerichtet* und hatte in seinem Maul drei Rippen zwischen seinen Zähnen. Und man sprach zu ihm so: Steh auf, friss viel Fleisch!*", footnotes: ["℘ Kap. 2,39; 8,3.4", "℘ Jes 13,18"] },
      { number: 6, text: "Nach diesem schaute ich, und siehe, ein anderes, wie ein Leopard: das hatte vier Vogelflügel auf seinem Rücken. Und das Tier hatte vier Köpfe*, und Herrschaft* wurde ihm gegeben*.", footnotes: ["℘ Kap. 8,21.22", "o. Macht", "℘ Kap. 2,39; 8,5.8"] },
      { number: 7, text: "Nach diesem schaute ich in Visionen der Nacht: Und siehe, ein viertes Tier, furchtbar und schreckenerregend und außergewöhnlich stark, und es hatte große eiserne Zähne; es fraß und zermalmte, und den Rest zertrat es mit seinen Füßen*. Und es war verschieden von allen Tieren, die vor ihm waren, und es hatte zehn Hörner*.", footnotes: ["℘ Kap. 2,40", "℘ Sach 2,1; Offb 13,1.2; 17,7.8"] },
      { number: 8, text: "Während ich auf die Hörner achtete, siehe, da stieg ein anderes, kleines Horn zwischen ihnen empor*, und drei von den ersten Hörnern wurden vor ihm ausgerissen; und siehe, an diesem Horn waren Augen wie Menschenaugen und ein Mund, der große <Worte>* redete*.", footnotes: ["℘ Kap. 8,9", "w. Großes; d. i. prahlerisch, vermessen", "℘ Kap. 11,36; Offb 13,5"] },
      { number: 9, text: "Ich schaute, bis Throne aufgestellt wurden* und einer, der alt war an Tagen*, sich setzte*. Sein Gewand war weiß wie Schnee und das Haar seines Hauptes wie reine Wolle*, sein Thron Feuerflammen, dessen Räder ein loderndes Feuer*.", footnotes: ["℘ Mt 19,28; Offb 20,4", "℘ Ps 90,2; 93,2", "℘ Jes 6,1; Hes 1,26; Offb 4,2", "℘ Offb 1,14", "℘ Hes 1,16.27"] },
      { number: 10, text: "Ein Feuerstrom floss und ging von ihm aus*. Tausend mal Tausende dienten ihm, und zehntausend mal Zehntausende standen vor ihm*. Das Gericht setzte sich, und Bücher wurden geöffnet*.", footnotes: ["℘ Ps 97,3; Jes 66,15", "℘ 1Kö 22,19; Hi 25,3; Ps 103,21; Lk 2,13; Hebr 12,22", "℘ Offb 20,12"] },
      { number: 11, text: "Dann schaute ich wegen der Stimme der großen Worte, die das Horn redete; ich schaute, bis das Tier getötet und sein Leib zerstört und dem Brand des Feuers übergeben wurde*.", footnotes: ["℘ Offb 19,20"] },
      { number: 12, text: "Und den übrigen Tieren wurde ihre Herrschaft weggenommen, und Lebensdauer wurde ihnen gegeben bis auf Zeit und Stunde." },
      { number: 13, text: "Ich schaute in Visionen der Nacht: Und siehe, mit den Wolken des Himmels kam einer wie der Sohn eines Menschen*. Und er kam zu dem Alten an Tagen, und man brachte ihn vor ihn.", footnotes: ["℘ Mt 24,30; 26,64; Joh 5,27; Offb 1,7.13"] },
      { number: 14, text: "Und ihm wurde Herrschaft* und Ehre und Königtum gegeben*, und alle Völker, Nationen und Sprachen dienten ihm*. Seine Herrschaft* ist eine ewige Herrschaft*, die nicht vergeht, und sein Königtum <so>, dass es nicht zerstört wird*.", footnotes: ["o. Macht", "℘ Ps 2,6-8; Mt 16,28; 28,18; Lk 21,27; Joh 3,35; 1Kor 15,27; Offb 5,7", "℘ Ps 103,19", "o. Macht", "o. Macht", "℘ Kap. 2,44; Jes 9,6; Joh 12,34; Offb 11,15.17"] },
      { number: 15, text: "*Mir, Daniel, wurde mein Geist tief in meinem Innern* bekümmert, und die Visionen meines Hauptes erschreckten mich*.", footnotes: ["℘ V. 15-28: V. 1-14", "w. mitten in seiner Scheide; d. h. in seinem Behältnis", "℘ Kap. 2,1"] },
      { number: 16, text: "Ich näherte mich einem von denen, die dastanden, und bat ihn um genaue Auskunft* über dies alles. Und er sprach zu mir und ließ mich die Deutung der Sachen* wissen:", footnotes: ["w. und erbat Zuverlässiges von ihm", "o. Worte"] },
      { number: 17, text: "Diese großen Tiere — es sind vier — <bedeuten>: vier Könige werden sich von der Erde her erheben." },
      { number: 18, text: "Aber die Heiligen des Höchsten werden das Reich* empfangen*, und sie werden das Reich* besitzen bis in Ewigkeit, ja, bis in die Ewigkeit der Ewigkeiten*.", footnotes: ["w. Königtum, o. Königreich", "℘ Lk 12,32", "w. Königtum, o. Königreich", "℘ Ob 17; Offb 22,5"] },
      { number: 19, text: "Daraufhin wollte ich Genaueres wissen* über das vierte Tier, das von allen anderen verschieden war, außergewöhnlich schreckenerregend, dessen Zähne aus Eisen und dessen Klauen aus Bronze waren, das fraß, zermalmte und den Rest mit seinen Füßen zertrat,", footnotes: ["w. wollte ich zuverlässig feststellen"] },
      { number: 20, text: "und über die zehn Hörner auf seinem Kopf und über das andere <Horn>, das emporstieg und vor dem drei <andere Hörner> ausfielen. Und das Horn hatte Augen und einen Mund, der große <Worte>* redete, und sein Aussehen war größer als das seiner Gefährten.", footnotes: ["w. Großes; d. i. prahlerisch, vermessen"] },
      { number: 21, text: "Ich sah, wie dieses Horn gegen die Heiligen Krieg führte* und sie besiegte*,", footnotes: ["℘ Offb 20,9", "℘ Kap. 8,9-12.24; 12,7; Offb 11,7; 13,7"] },
      { number: 22, text: "bis der, der alt an Tagen war, kam und das Gericht den Heiligen des Höchsten gegeben wurde* und die Zeit anbrach, dass die Heiligen das Königreich in Besitz nahmen*. —", footnotes: ["℘ 1Kor 6,2; Offb 20,4", "℘ Ps 149,5-9"] },
      { number: 23, text: "Er sprach so: Das vierte Tier <bedeutet>: Ein viertes Königreich wird auf Erden sein, das von allen <anderen> Königreichen verschieden sein wird. Es wird die ganze Erde auffressen und sie zertreten und sie zermalmen*.", footnotes: ["℘ Kap. 2,40"] },
      { number: 24, text: "Und die zehn Hörner <bedeuten>: Aus diesem Königreich werden sich zehn Könige erheben*. Und ein anderer wird sich nach ihnen erheben, und dieser wird verschieden sein von den vorigen, und er wird drei Könige erniedrigen.", footnotes: ["℘ Offb 17,12"] },
      { number: 25, text: "Und er wird Worte reden gegen den Höchsten und wird die Heiligen des Höchsten aufreiben*; und er wird danach trachten, Festzeiten und Gesetz zu ändern*, und sie werden in seine Hand gegeben werden für eine Zeit und <zwei> Zeiten und eine halbe Zeit*.", footnotes: ["℘ Kap. 8,9-12.24; 12,7; Offb 11,7; 13,7", "℘ Kap. 8,11; 9,27; Offb 13,15-17", "o. sie werden ein Jahr und <zwei> Jahre und ein halbes Jahr in seine Hand gegeben werden. — Das hier verwendete Wort kann sowohl »Zeit«, d. h. Zeitabschnitt, als auch »Jahr« heißen.\n℘ Kap. 12,7; Offb 11,2.3; 12,14"] },
      { number: 26, text: "Aber das Gericht wird sich setzen; und man wird seine Herrschaft wegnehmen, um sie zu vernichten und zu zerstören bis zum Ende*.", footnotes: ["℘ Kap. 11,45; Offb 11,18"] },
      { number: 27, text: "Und das Reich* und die Herrschaft und die Größe der Reiche* unter dem ganzen Himmel wird dem Volk der Heiligen des Höchsten gegeben werden*. Sein Reich* ist ein ewiges Reich*, und alle Mächte werden ihm dienen und gehorchen. —", footnotes: ["w. Königtum, o. Königreich", "w. Königtum, o. Königreich", "℘ Lk 12,32", "w. Königtum, o. Königreich", "w. Königtum, o. Königreich\n℘ Apg 1,6"] },
      { number: 28, text: "Hier endet der Bericht*. Mich, Daniel, ängstigten meine Gedanken sehr*, und meine Gesichtsfarbe veränderte sich an mir. Und ich bewahrte die Sache* in meinem Herzen*.", footnotes: ["w. Bis hierher das Ende der Sache o. der Rede", "℘ Kap. 4,16; 8,27", "o. das Wort", "℘ 1Mo 37,11"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Im dritten Jahr der Regierung des Königs Belsazar* erschien mir, Daniel, eine Vision nach der, die mir im Anfang erschienen war.", heading: "Daniels Vision vom Widder und Ziegenbock", footnotes: ["℘ Kap. 7,1"] },
      { number: 2, text: "Und ich sah in der Vision: Und es geschah, während ich sah, da war ich in der Burg Susa*, die in der Provinz Elam* ist; und ich sah in der Vision, dass ich am Fluss Ulai war.", footnotes: ["℘ Neh 1,1; Est 1,2", "℘ Jes 21,2"] },
      { number: 3, text: "Und ich erhob meine Augen und sah: Und siehe, ein Widder stand vor dem Fluss, der hatte zwei Hörner; und die zwei Hörner waren hoch, und das eine war höher als das zweite, und das höhere stieg zuletzt auf." },
      { number: 4, text: "Ich sah den Widder nach Westen und nach Norden und nach Süden stoßen, und kein Tier hielt ihm stand, und niemand rettete aus seiner Hand; und er handelte nach seinem Belieben und wurde groß*.", footnotes: ["o. tat groß\n℘ Kap. 7,5; 11,2; Jes 45,1.2"] },
      { number: 5, text: "Und während ich achtgab, siehe, da kam ein Ziegenbock* von Westen her über die ganze Erde, und er berührte die Erde nicht; und der Bock hatte ein ansehnliches Horn* zwischen seinen Augen*.", footnotes: ["℘ Kap. 7,6", "o. ein Horn der prophetischen Schau", "℘ Kap. 11,3"] },
      { number: 6, text: "Und er kam zu dem Widder mit den zwei Hörnern, den ich vor dem Fluss hatte stehen sehen; und im Zorn seiner Kraft rannte er auf ihn zu." },
      { number: 7, text: "Und ich sah ihn neben dem Widder eintreffen*, und er ergrimmte gegen ihn, und er stieß den Widder und zerbrach seine beiden Hörner; und in dem Widder war keine Kraft, vor ihm zu bestehen. Und er warf ihn zu Boden und zertrat ihn, und niemand rettete den Widder aus seiner Hand.", footnotes: ["w. die Seite des Widders erreichen"] },
      { number: 8, text: "Und der Ziegenbock wurde überaus groß. Und als er stark geworden war, zerbrach das große Horn, und vier ansehnliche <Hörner> wuchsen an seiner Stelle* nach den vier Winden des Himmels hin.", footnotes: ["w. und es erwuchsen <zur> Schau vier an seiner Stelle"] },
      { number: 9, text: "Und aus dem einen von ihnen kam ein einzelnes Horn hervor*, <zunächst> klein*, aber es wurde übermäßig groß gegen Süden und gegen Osten und gegen die Zierde*.", footnotes: ["℘ Kap. 7,8; 11,21", "w. von Kleinheit", "d. h. gegen das Land der Zierde: Israel\n℘ Kap. 11,16.41; Hes 20,6.15"] },
      { number: 10, text: "Und es wuchs bis an das Heer des Himmels*, und es warf <einige> von dem Heer und von den Sternen zur Erde herab* und zertrat sie.", footnotes: ["℘ Jes 14,13", "℘ Offb 12,4"] },
      { number: 11, text: "Selbst bis an den Obersten des Heeres* wuchs er* <empor>*. Und er nahm ihm das regelmäßige <Opfer> weg*, und die Stätte seines Heiligtums wurde gestürzt*.", footnotes: ["℘ Jos 5,14", "d. i. der mit dem Horn gemeinte Mensch", "o. tat er groß\n℘ Kap. 5,23; 11,22", "o. Und das regelmäßige <Opfer> wurde von ihm aufgehoben\n℘ Kap. 12,11; 4Mo 28,3", "℘ Kap. 7,25"] },
      { number: 12, text: "Und ein <Opfer>dienst wurde verbrecherisch gegen das regelmäßige <Opfer> eingerichtet*. Und <das Horn> warf die Wahrheit zu Boden und hatte Erfolg*.", footnotes: ["o. Und ein Heer wurde verbrecherisch gegen das regelmäßige <Opfer> eingesetzt; o. Und Mühsal wurde frevlerisch auf das regelmäßige <Opfer> gelegt", "℘ Kap. 7,21.25; 11,28"] },
      { number: 13, text: "Und ich hörte einen Heiligen* reden. Und es sprach ein Heiliger zu jemandem — dem Redenden <nämlich> —: Bis wann <gilt> die Vision von dem regelmäßigen <Opfer> und von dem entsetzlichen Verbrechen, *dass sowohl das Heiligtum als auch der <Opfer>dienst zur Zertretung preisgegeben sind*?*", footnotes: ["℘ Kap. 4,10", "o. von Preisgabe und Heiligtum und Heer (o. Mühsal) <und> Zertretung", "o. von Preisgabe und Heiligtum und Heer (o. Mühsal) <und> Zertretung", "℘ Kap. 11,31; 12,6.11"] },
      { number: 14, text: "Und er sagte zu mir: Bis zu 2 300 Abenden und Morgen*; dann wird das Heiligtum <wieder> gerechtfertigt.", footnotes: ["w. 2 300 Abend-Morgen. — Diese Angabe bezieht sich auf das ständige Opfer, das abends und morgens dargebracht wurde. Somit sind wohl 1 150 Tage gemeint."] },
      { number: 15, text: "Und es geschah, als ich, Daniel, die Vision gesehen hatte, da suchte ich Verständnis <darüber>. Und siehe, da stand vor mir <einer, sein Aussehen war> wie das Aussehen eines Mannes." },
      { number: 16, text: "Und ich hörte eine Menschenstimme zwischen <den Ufern des> Ulai, die rief und sprach: Gabriel*, lass diesen die Erscheinung verstehen*!", footnotes: ["℘ Kap. 9,21; Lk 1,19.26", "℘ Sach 1,9; Offb 1,1"] },
      { number: 17, text: "Und er trat an den Ort, wo ich stand; und als er herantrat, erschrak ich und fiel nieder auf mein Angesicht*. Er aber sprach zu mir: Merke auf, Menschensohn*! Denn die Vision <gilt> für die Zeit des Endes*.", footnotes: ["℘ Hes 1,28", "℘ Hes 2,1", "℘ Kap. 11,27.35; 12,4; Hab 2,3"] },
      { number: 18, text: "Und als er mit mir redete, sank ich betäubt zur Erde auf mein Angesicht*. Er aber rührte mich an und stellte mich auf meinen <vorigen> Platz*.", footnotes: ["℘ Offb 1,17", "℘ Kap. 10,9.10; Hes 2,2; Sach 4,1"] },
      { number: 19, text: "Und er sagte: Siehe, ich will dich erkennen lassen, was am Ende der Verfluchung* geschehen wird; denn es <gilt> für die <festgesetzte> Zeit des Endes*.", footnotes: ["℘ Kap. 11,36", "℘ Kap. 11,27.35; 12,4; Hab 2,3"] },
      { number: 20, text: "Der Widder mit den zwei Hörnern, den du gesehen hast, <das> sind die Könige von Medien und Persien*.", footnotes: ["℘ Kap. 5,28"] },
      { number: 21, text: "Und der zottige Ziegenbock ist der König von Griechenland*. Und das große Horn, das zwischen seinen Augen war, das ist der erste König.", footnotes: ["℘ Kap. 2,39; Sach 9,13"] },
      { number: 22, text: "Und dass es zerbrach und dass vier <andere> an seiner Stelle auftraten<, bedeutet>: Vier Königreiche werden aus der Nation aufstehen, aber nicht mit seiner Macht*.", footnotes: ["℘ Kap. 7,6; 11,4"] },
      { number: 23, text: "Und am Ende ihrer Königsherrschaft, wenn die Abgefallenen* das Maß vollgemacht haben, wird ein König aufstehen, mit hartem Gesicht und erfahren in Ränken.", footnotes: ["o. Verbrecher; o. Frevler"] },
      { number: 24, text: "Und seine Macht wird stark sein*, jedoch nicht durch seine eigene Macht*; und er wird entsetzliches Verderben anrichten und wird erfolgreich sein und handeln. Und er wird die Starken und das Volk der Heiligen vernichten*.", footnotes: ["℘ Kap. 11,23; Ps 37,35; Offb 13,5", "Andere üs. mit Textänderung: aber nicht so mächtig wie er (d. h. der erste König)", "℘ Kap. 11,31-36"] },
      { number: 25, text: "Und wegen seines Verstandes wird er erfolgreich sein, <mit> Betrug* in seiner Hand. Und er wird in seinem Herzen großtun, und unversehens* wird er viele vernichten. Und gegen den Fürsten der Fürsten* wird er sich auflehnen, aber ohne eine <Menschen>hand wird er zerbrochen werden*.", footnotes: ["o. Hinterlist", "w. in Sorglosigkeit; d. h. im Frieden", "d. i. Gott\n℘ Offb 17,14", "℘ Kap. 11,45; Hi 34,20; Kla 4,6"] },
      { number: 26, text: "Und die Erscheinung von den Abenden und von den Morgen*: was gesagt wurde, ist Wahrheit. Du aber, halte die Vision geheim*, denn es sind noch viele Tage bis dahin*.", footnotes: ["w. von Abend und Morgen; vgl. V. 14", "o. verschließe die Vision\n℘ Kap. 12,4.9; Offb 10,4", "w. denn es ist für viele Tage\n℘ Kap. 10,14"] },
      { number: 27, text: "Und ich, Daniel, war erschöpft und <einige> Tage krank*. Dann stand ich auf und verrichtete die Geschäfte des Königs. Und ich war entsetzt über die Erscheinung, und keiner war da, der es verstand*.", footnotes: ["℘ Kap. 7,28; 10,8", "o. deutete"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Im ersten Jahr des Darius, des Sohnes des Ahasveros, vom Geschlecht* der Meder*, der über das Reich der Chaldäer König geworden war,", heading: "Daniels Bußgebet und das Geheimnis der siebzig Jahrwochen", footnotes: ["w. Samen", "℘ Kap. 6,1"] },
      { number: 2, text: "im ersten Jahr seiner Königsherrschaft achtete ich, Daniel, in den Bücherrollen* auf die Zahl der Jahre, über die das Wort des HERRN zum Propheten Jeremia geschehen war, dass <nämlich> siebzig Jahre über den Trümmern Jerusalems dahingehen sollten*.", footnotes: ["℘ Offb 1,3", "w. für die Trümmerstätten Jerusalems vollendet werden sollten\n℘ 2Chr 36,21; Jer 25,11; Hes 29,11"] },
      { number: 3, text: "Und ich richtete mein Gesicht zu Gott, dem Herrn, hin, um <ihn> mit Gebet und Flehen zu suchen*, in Fasten* und Sack und Asche*.", footnotes: ["℘ Jer 29,12", "℘ 2Sam 12,16; Esr 8,21; Neh 1,4", "℘ Est 4,1; Hi 42,6"] },
      { number: 4, text: "Und ich betete zum HERRN, meinem Gott, und ich bekannte* und sprach: Ach, Herr, du großer und furchtbarer Gott, der Bund und Güte* denen bewahrt, die ihn lieben und seine Gebote halten*!", footnotes: ["℘ 3Mo 26,40", "o. Gnade; o. Treue", "℘ 2Mo 20,6; 5Mo 7,9.12; Neh 1,5"] },
      { number: 5, text: "Wir haben gesündigt und haben uns vergangen und haben gottlos gehandelt, und wir haben uns aufgelehnt und sind von deinen Geboten und von deinen Rechtsbestimmungen abgewichen*.", footnotes: ["℘ 2Kö 21,15; 2Chr 6,37; Neh 1,6.7; Jes 64,4.5; Jer 14,20; Kla 3,42; Hes 5,6"] },
      { number: 6, text: "Und wir haben nicht auf deine Knechte, die Propheten*, gehört, die in deinem Namen zu unseren Königen, unseren Obersten und unseren Vätern und zum ganzen Volk des Landes geredet haben*.", footnotes: ["℘ Offb 10,7", "℘ 2Chr 36,16; Neh 9,30.34; Jer 7,24.26; Sach 1,4"] },
      { number: 7, text: "Bei dir, Herr, ist die Gerechtigkeit*, bei uns aber ist die Beschämung des Angesichts, wie es an diesem Tag ist: bei den Männern von Juda und den Bewohnern von Jerusalem und dem ganzen Israel*, den Nahen und den Fernen, in allen Ländern, wohin du sie vertrieben hast wegen ihrer Untreue, die sie gegen dich begangen haben*.", footnotes: ["℘ Esr 9,15; Ps 119,137; Jer 12,1", "℘ Esr 9,6.7", "℘ Jer 32,32; Hes 5,10"] },
      { number: 8, text: "HERR! Bei uns ist die Beschämung des Angesichts*, bei unseren Königen, unseren Obersten und unseren Vätern, weil wir gegen dich gesündigt haben*.", footnotes: ["℘ Jer 7,19", "℘ 2Kö 21,15; 2Chr 6,37; Neh 1,6.7; Jes 64,4.5; Jer 14,20; Kla 3,42; Hes 5,6"] },
      { number: 9, text: "Bei dem Herrn, unserem Gott, ist das Erbarmen und die Vergebung*. Denn wir haben uns gegen ihn aufgelehnt*,", footnotes: ["℘ Ps 130,4; Kla 3,22", "℘ Neh 9,17; Jer 14,7"] },
      { number: 10, text: "und wir haben nicht auf die Stimme des HERRN, unseres Gottes, gehört, <der uns gebot,> in seinen Gesetzen zu leben*, die er uns durch seine Knechte, die Propheten*, vorgelegt hat.", footnotes: ["w. zu gehen", "℘ Offb 10,7"] },
      { number: 11, text: "Und ganz Israel hat dein Gesetz übertreten und ist abgewichen, so dass sie deiner Stimme nicht gehorcht haben*. Und so hat sich der Fluch und der Schwur über uns ergossen, der im Gesetz des Mose, des Knechtes Gottes, geschrieben steht, weil wir gegen ihn* gesündigt haben*.", footnotes: ["℘ 5Mo 8,20; 2Kö 18,12; Jer 6,19; 16,11", "einige Handschr.: gegen dich", "℘ 5Mo 28,15; 2Kö 22,16; Jer 30,14; 44,23"] },
      { number: 12, text: "Und er hat seine Worte* erfüllt, die er geredet hat über uns und über unsere Richter, die uns richteten, <nämlich> ein großes Unglück über uns zu bringen*, so dass unter dem ganzen Himmel nichts <Derartiges> geschehen ist wie das, was an Jerusalem geschehen ist*.", footnotes: ["so mit der Schreibform des Mas. T.; mit der Leseform: sein Wort", "℘ Jes 43,28; Jer 39,16; Kla 2,17; Sach 1,6", "℘ Jer 30,7; Kla 1,12; Hes 5,9"] },
      { number: 13, text: "Wie es im Gesetz des Mose geschrieben steht, so ist all dies Unglück über uns gekommen*. Und wir haben das Angesicht des HERRN, unseres Gottes, nicht besänftigt, indem wir von unserer Schuld umgekehrt wären und achtgehabt hätten auf deine Wahrheit*.", footnotes: ["℘ 5Mo 28,15; 2Kö 22,16; Jer 30,14; 44,23", "℘ Jes 43,22; 64,6; Jer 5,3"] },
      { number: 14, text: "Und so war der HERR auf das Unglück bedacht* und ließ es über uns kommen*. Denn der HERR, unser Gott, ist gerecht* in allen seinen Taten*, die er tut. Aber wir haben nicht auf seine Stimme gehört*.", footnotes: ["w. Und so wachte der HERR über dem Unglück", "℘ Jer 44,27; Hes 16,43", "℘ Kap. 4,34; 2Mo 9,27; Esr 9,15", "℘ Esr 9,15; Ps 119,137; Jer 12,1", "℘ Jer 4,17; Kla 1,5"] },
      { number: 15, text: "Und nun, Herr, unser Gott, der du dein Volk aus dem Land Ägypten mit starker Hand herausgeführt* und dir einen Namen gemacht hast, wie es an diesem Tag ist*! Wir haben gesündigt, wir haben gottlos gehandelt*.", footnotes: ["℘ 2Kö 21,15; 2Chr 6,37; Neh 1,6.7; Jes 64,4.5; Jer 14,20; Kla 3,42; Hes 5,6", "℘ Neh 9,10", "℘ Neh 9,10"] },
      { number: 16, text: "Herr, nach all <den Taten> deiner Gerechtigkeit mögen doch dein Zorn und deine Erregung sich wenden von deiner Stadt Jerusalem, dem Berg deines Heiligtums! Denn wegen unserer Sünden und wegen der Vergehen unserer Väter sind Jerusalem und dein Volk zum Hohn geworden für alle rings um uns her*.", footnotes: ["℘ Ps 79,4; Kla 2,15.16; Hes 22,4"] },
      { number: 17, text: "Und nun, unser Gott, höre auf das Gebet deines Knechtes und auf sein Flehen*! Und lass dein Angesicht leuchten* über dein verwüstetes Heiligtum* um des Herrn willen!", footnotes: ["℘ 1Kö 8,28; Kla 3,56", "℘ 4Mo 6,25", "℘ Ps 67,2; 74,3"] },
      { number: 18, text: "Neige, mein Gott, dein Ohr und höre! Tu deine Augen auf und sieh* unsere Verwüstungen und die Stadt, über der dein Name ausgerufen ist*! Denn nicht aufgrund unserer Gerechtigkeiten legen wir unser Flehen vor dich hin*, sondern aufgrund deiner vielen Erbarmungen*.", footnotes: ["℘ 2Kö 19,16; Jes 37,17", "d. h. die Stadt, die dir gehört\n℘ 4Mo 6,27; Jes 43,7; 63,19; Jer 7,11", "℘ Ps 25,6.7", "℘ Hes 36,22.32"] },
      { number: 19, text: "Herr, höre! Herr, vergib!* Herr, merke auf und handle! Zögere nicht, um deiner selbst willen, mein Gott*! Denn dein Name ist über deiner Stadt und deinem Volk ausgerufen worden*.*", footnotes: ["℘ 4Mo 14,19; 1Kö 8,30", "℘ Ps 79,9", "d. h. sie gehören dir", "℘ Jes 63,19"] },
      { number: 20, text: "Während ich noch redete und betete und meine Sünde und die Sünde meines Volkes Israel bekannte* und mein Flehen für den heiligen Berg meines Gottes vor den HERRN, meinen Gott, hinlegte —", footnotes: ["℘ Esr 10,1"] },
      { number: 21, text: "und während ich noch redete im Gebet, da, zur Zeit des Abendopfers*, *rührte mich der Mann Gabriel an, den ich am Anfang in der Vision gesehen hatte*, als ich ganz ermattet war*.", footnotes: ["℘ Esr 9,4", "o. erreichte mich wie in raschem Flug der Mann Gabriel, den ich am Anfang im Gesicht gesehen hatte", "℘ Kap. 8,16", "o. erreichte mich wie in raschem Flug der Mann Gabriel, den ich am Anfang im Gesicht gesehen hatte"] },
      { number: 22, text: "Und er wusste Bescheid*, redete mit mir und sagte: Daniel, jetzt bin ich ausgegangen, um dich Verständnis zu lehren.", footnotes: ["o. gab Verständnis"] },
      { number: 23, text: "Am Anfang deines Flehens ist ein Wort ergangen, und ich bin gekommen, um <es dir> mitzuteilen*. Denn du bist ein Vielgeliebter*. So achte nun auf das Wort und verstehe die Erscheinung*:", footnotes: ["℘ 2Kö 19,20", "w. Kostbarkeiten, o. Schatz\n℘ Kap. 10,11; Spr 15,8.9; Hes 14,14", "℘ Kap. 10,1; 2Tim 2,7"] },
      { number: 24, text: "Siebzig Wochen* sind über dein Volk und über deine heilige Stadt bestimmt*, um das Verbrechen zum Abschluss zu bringen* und den Sünden ein Ende zu machen* und die Schuld zu sühnen* und eine ewige Gerechtigkeit einzuführen* und Vision und Propheten zu versiegeln und ein Allerheiligstes zu salben.", footnotes: ["das sind Jahrwochen; d. h. Abschnitte zu je sieben Jahren", "℘ Hes 4,5.6", "Andere üs.: den Frevel zu zügeln", "so mit der Leseform des Mas. T.; mit der Schreibform: um die Sünden zu versiegeln\n℘ Hebr 9,26", "w. zu bedecken", "℘ Jes 42,4; 51,6.8; 53,11; Röm 5,19; 2Kor 5,21"] },
      { number: 25, text: "So sollst du denn erkennen und verstehen: Von dem <Zeitpunkt an, als das> Wort erging, Jerusalem wiederherzustellen und zu bauen*, bis zu einem Gesalbten, einem Fürsten*, sind es *sieben Wochen*. Und 62 Wochen <lang> werden Platz und Stadtgraben* wiederhergestellt und *gebaut sein, und zwar in der Bedrängnis* der Zeiten*.", footnotes: ["℘ Neh 2,5.6.8", "℘ Mi 5,1", "LXX und Vulg.: sieben Wochen und 62 Wochen. Und Platz und Stadtgraben werden", "das sind Jahrwochen; d. h. Abschnitte zu je sieben Jahren", "das sind Jahrwochen; d. h. Abschnitte zu je sieben Jahren", "o. gebaut werden. Aber in der Bedrängnis der Zeiten 26 und nach den", "Andere üs. in Anlehnung an LXX: am Ende", "℘ Neh 4,2-8"] },
      { number: 26, text: "Und nach den* 62 Wochen* wird ein Gesalbter ausgerottet werden* und wird keine <Hilfe> finden*. Und das Volk eines kommenden Fürsten wird die Stadt und das Heiligtum zerstören*, und sein Ende ist in einer Überflutung*; und bis zum Ende ist Krieg, fest beschlossene Verwüstungen*.", footnotes: ["o. gebaut werden. Aber in der Bedrängnis der Zeiten 26 und nach den", "das sind Jahrwochen; d. h. Abschnitte zu je sieben Jahren", "℘ Jes 53,8; Mt 26,24; Lk 17,25", "w. und ihm wird nichts sein", "℘ Lk 19,43.44", "℘ Kap. 11,10; Jes 28,2", "℘ Kap. 11,36; Jes 28,22; Lk 21,6.24"] },
      { number: 27, text: "Und stark machen wird er einen Bund für die Vielen*, eine Woche lang*; und zur Hälfte* der Woche wird er Schlachtopfer und Speisopfer aufhören lassen*. Und auf dem Flügel von Gräueln <kommt> ein Verwüster*, bis fest beschlossene Vernichtung* über den Verwüster ausgegossen wird*.", footnotes: ["o. Und stark erweisen wird sich der Bund mit den Vielen. — Andere üs.: er wird den Bund für viele schwer machen; d. h. viele zum Abfall bringen\n℘ Mt 24,12", "℘ Jes 28,15.18", "d. h. in der Mitte", "℘ Kap. 7,25", "℘ Mt 24,15", "℘ Jes 10,22.23", "℘ Kap. 11,36; Jes 28,22; Lk 21,6.24"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Im dritten Jahr des Kyrus, des Königs von Persien*, wurde dem Daniel, der Beltschazar genannt wurde*, ein Wort offenbart. Und das Wort ist Wahrheit und <betrifft> eine große Mühsal. Und er verstand das Wort, und Verständnis wurde ihm in der Erscheinung <zuteil>*. —", heading: "Daniels Zubereitung für weitere Weissagungen", footnotes: ["℘ Kap. 1,21", "℘ Kap. 1,7", "℘ Kap. 1,17; 9,23"] },
      { number: 2, text: "In jenen Tagen trauerte ich, Daniel, drei volle Wochen*.", footnotes: ["℘ Neh 1,4"] },
      { number: 3, text: "Köstliche Speise aß ich nicht, und weder Fleisch noch Wein kamen in meinen Mund; und ich salbte mich nicht, bis drei volle Wochen um waren." },
      { number: 4, text: "Und am 24. Tag des ersten Monats, da war ich am Ufer des großen Stromes, das ist der Hiddekel*.", footnotes: ["d. i. der Tigris\n℘ Kap. 12,5; 1Mo 2,14"] },
      { number: 5, text: "Und ich erhob meine Augen und sah: Und siehe, da war ein Mann, in Leinen gekleidet, und seine Hüften waren umgürtet mit Gold von Ufas*.", footnotes: ["einige Handschr.: Ophir\n℘ Jer 10,9; Offb 1,13"] },
      { number: 6, text: "Und sein Leib war wie ein Türkis und sein Gesicht wie das Aussehen eines Blitzes. Und seine Augen waren wie Feuerfackeln und seine Arme und seine Füße* wie der Anblick von glatter Bronze*. Und der Klang seiner Worte war wie der Klang einer <Volks>menge*.", footnotes: ["w. seine Fuß-Enden", "℘ Hes 1,7; 8,2", "℘ Hes 1,24; Offb 1,14-16"] },
      { number: 7, text: "Aber nur ich, Daniel, allein sah die Erscheinung. Die Männer, die bei mir waren, sahen die Erscheinung nicht*; doch fiel eine große Angst auf sie, und sie flohen und versteckten sich.", footnotes: ["℘ Apg 9,7; 22,9"] },
      { number: 8, text: "Und ich blieb allein übrig und sah diese große Erscheinung. Und es blieb keine Kraft in mir, und meine Gesichtsfarbe veränderte sich an mir bis zur Entstellung, und ich behielt keine Kraft*.", footnotes: ["℘ Kap. 8,27; Offb 1,17"] },
      { number: 9, text: "Und ich hörte den Klang seiner Worte. Und als ich den Klang seiner Worte hörte, lag ich betäubt auf meinem Gesicht, mit meinem Gesicht zur Erde*.", footnotes: ["℘ Kap. 8,18; Hab 3,16"] },
      { number: 10, text: "Und siehe, eine Hand rührte mich an und rüttelte mich auf, <so dass ich wieder> auf meine Knie und Handflächen <kam>." },
      { number: 11, text: "Und er sprach zu mir: Daniel, du vielgeliebter Mann*! Achte auf die Worte, die ich zu dir rede, und steh an deinem Platz! Denn ich bin jetzt zu dir gesandt*. Und als er dieses Wort mit mir redete, stand ich zitternd auf.", footnotes: ["w. Mann der Kostbarkeiten", "℘ Kap. 9,22.23"] },
      { number: 12, text: "Und er sprach zu mir: Fürchte dich nicht, Daniel! Denn vom ersten Tag an, als du dein Herz darauf gerichtet hast, Verständnis zu erlangen und dich vor deinem Gott zu demütigen, sind deine Worte erhört worden*. Und um deiner Worte willen bin ich gekommen*.", footnotes: ["℘ Lk 1,13", "℘ Kap. 9,22.23"] },
      { number: 13, text: "Aber der Fürst des Königreichs Persien* stand mir 21 Tage entgegen. Und siehe, Michael*, einer der ersten Fürsten*, kam, um mir zu helfen, und ich wurde dort entbehrlich* bei den Königen von Persien.", footnotes: ["℘ Esr 4,4.5", "℘ Kap. 12,1; Jud 9", "℘ Kap. 9,22.23", "w. ich blieb übrig. — LXX: ich ließ ihn allein"] },
      { number: 14, text: "Und ich bin gekommen, um dich verstehen zu lassen, was deinem Volk am Ende der Tage widerfahren wird*; denn noch <gilt> die Vision für <ferne> Tage*.", footnotes: ["℘ Kap. 2,28; 1Mo 49,1; 4Mo 24,14; 5Mo 4,30; Hes 38,16; Hos 3,5", "℘ Kap. 8,26"] },
      { number: 15, text: "Und als er in dieser Weise* mit mir redete, richtete ich mein Gesicht zur Erde und verstummte.", footnotes: ["w. entsprechend diesen Worten"] },
      { number: 16, text: "Und siehe, einer, den Menschenkindern gleich, berührte meine Lippen*. Und ich öffnete meinen Mund und redete und sprach zu dem, der vor mir stand: Mein Herr, bei der Erscheinung überfielen mich meine Wehen, und ich habe keine Kraft behalten.", footnotes: ["℘ Jes 6,7; Jer 1,9"] },
      { number: 17, text: "Und wie kann der Knecht dieses meines Herrn mit diesem meinem Herrn reden? Und ich — von nun an bleibt keine Kraft mehr in mir, und kein Odem ist in mir übrig." },
      { number: 18, text: "Da rührte er, <der> im Aussehen wie ein Mensch <war>, mich wieder an und stärkte mich*.", footnotes: ["℘ Ps 138,3"] },
      { number: 19, text: "Und er sprach: Fürchte dich nicht*, du vielgeliebter Mann*! Friede <sei mit> dir! Sei stark, ja, sei stark!* Und als er mit mir redete, wurde ich stark und sagte: Mein Herr möge reden! Denn du hast mich gestärkt*.", footnotes: ["℘ Ri 6,23", "w. Mann der Kostbarkeiten", "℘ Jos 1,6.7; Jes 35,4", "℘ Ps 138,3"] },
      { number: 20, text: "Da sprach er: Hast du erkannt, warum ich zu dir gekommen bin? Nun aber kehre ich zurück, um gegen den Fürsten von Persien* zu kämpfen. Und wenn ich mit ihm fertig geworden bin*, siehe, dann wird der Fürst von Griechenland kommen —", footnotes: ["℘ Esr 4,4.5", "w. Und komme ich <da> heraus"] },
      { number: 21, text: "doch will ich dir mitteilen, was im Buch der Wahrheit aufgezeichnet ist* —, und es gibt keinen Einzigen, der mir gegen jene mutig beisteht* als nur Michael, euer Fürst.", footnotes: ["℘ Kap. 11,2; Offb 22,6", "o. der gegen jene treu zu mir hält"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und ich — im ersten Jahr des Meders Darius* war es meine Aufgabe*, ihm Helfer und Schutz zu sein*.", footnotes: ["℘ Kap. 6,1", "w. mein Platz", "℘ Ps 103,20.21"] },
      { number: 2, text: "Und nun will ich dir die Wahrheit mitteilen*: Siehe, noch drei Könige werden in Persien aufstehen*, und der vierte wird größeren Reichtum erlangen als alle*. Und wenn er durch seinen Reichtum mächtig geworden ist, wird er alles gegen das Königreich Griechenland aufbieten*.", heading: "Weissagungen über Persien, Griechenland, die Könige des Südens und Nordens — Israels Bedrängnisse und Rettung in der Endzeit", footnotes: ["℘ Kap. 10,21", "℘ Esr 4,6.7.24", "℘ Kap. 8,4; Est 1,1", "w. aufwecken"] },
      { number: 3, text: "Und ein tapferer* König wird aufstehen, und er wird mit großer Macht herrschen und nach seinem Belieben handeln*.", footnotes: ["o. gewaltiger", "℘ Kap. 8,5"] },
      { number: 4, text: "Aber sobald er aufgetreten ist, wird sein Königreich zertrümmert und nach den vier Winden des Himmels hin zerteilt werden*. Doch nicht für seine Nachkommen <wird es sein> und nicht der Macht entsprechend, mit der er geherrscht hat; denn sein Königreich wird zerstört und anderen zuteil werden, unter Ausschluss von jenen.", footnotes: ["℘ Kap. 8,8.22"] },
      { number: 5, text: "Und der König des Südens* wird mächtig werden, aber <auch einer> von seinen Obersten, und der wird mächtig sein über ihn hinaus und wird herrschen, seine Herrschaft wird eine große Herrschaft sein.", footnotes: ["℘ Sach 6,6"] },
      { number: 6, text: "Und nach Jahren* werden sie sich verbünden; und die Tochter des Königs des Südens wird zum König des Nordens kommen, um ein Abkommen zu treffen. Aber sie wird die Kraft des Armes* nicht behalten, und auch er und sein Arm* werden nicht bestehen. Und sie wird dahingegeben werden, sie und die sie kommen ließen*, und der, der sie gezeugt, und der, der sie <zur Frau> genommen hat* in <jenen> Zeiten.", footnotes: ["w. gegen Ende der Jahre", "d. h. der Streitmacht", "d. h. seine Streitmacht", "o. die sie gebracht haben; d. h. ihr Gefolge", "o. der sie unterstützt hat"] },
      { number: 7, text: "Und aus dem Spross ihrer Wurzeln steht einer an seiner Stelle auf*. Der wird gegen die Heeresmacht kommen und wird in die Festungen des Königs des Nordens eindringen und mit ihnen <nach Belieben> verfahren und wird sich als mächtig erweisen.", footnotes: ["o. steht einer an seiner Stelle; d. h. behauptet sich einer"] },
      { number: 8, text: "Auch wird er ihre Götter samt ihren gegossenen Bildern und ihren kostbaren Geräten, Silber und Gold, nach Ägypten entführen*. Und er wird <einige> Jahre ablassen vom König des Nordens.", footnotes: ["w. nach Ägypten in die Gefangenschaft führen\n℘ Jes 46,1.2"] },
      { number: 9, text: "Und der wird in das Reich des Königs des Südens kommen, aber <wieder> in sein Land zurückkehren." },
      { number: 10, text: "Aber seine Söhne werden sich <zum Krieg> rüsten und eine Menge großer Heere zusammenbringen; und sie* wird kommen, kommen und überschwemmen und überfluten* und wird <dann> umkehren. Und sie werden sich <wieder> rüsten <zum Vormarsch> bis zu seiner Festung.", footnotes: ["d. h. die Menge", "℘ Kap. 9,26"] },
      { number: 11, text: "Und der König des Südens wird zornig werden und wird ausziehen und gegen ihn, den König des Nordens, kämpfen. Und er* wird eine große Menge <Truppen> aufstellen, aber die Menge wird in seine Hand gegeben werden.", footnotes: ["o. Doch der"] },
      { number: 12, text: "Und wenn die Menge weggenommen wird, wird sein Herz sich erheben; und er wird Zehntausende niederwerfen, aber nicht mächtig bleiben." },
      { number: 13, text: "Und der König des Nordens wird wiederkommen und eine Menge <Truppen> aufstellen, größer als die frühere; und nach Ablauf* der Zeiten, nach Jahren, wird er mit einem großen Heer und mit großer Ausrüstung kommen.", footnotes: ["w. gegen Ende"] },
      { number: 14, text: "Und in jenen Zeiten werden viele gegen den König des Südens aufstehen; und Gewalttätige deines Volkes werden sich erheben, um die Vision zu erfüllen, und sie werden zu Fall kommen." },
      { number: 15, text: "Und der König des Nordens wird kommen und einen Wall aufschütten und eine befestigte Stadt einnehmen. Und die Streitkräfte* des Südens werden nicht standhalten, selbst sein auserlesenes Volk nicht. Sie werden keine Kraft haben standzuhalten.", footnotes: ["w. Arme"] },
      { number: 16, text: "Und der, der gegen ihn gekommen ist, wird nach seinem Belieben handeln, und niemand kann vor ihm bestehen. Und im Land der Zierde* wird er <mit seinem Heer> stehen, und Vernichtung wird in seiner Hand sein.", footnotes: ["d. i. Israel\n℘ V. 41.45; Kap. 8,9"] },
      { number: 17, text: "Und er wird sein Angesicht darauf richten, in den Besitz* seines ganzen Reiches zu kommen, und *wird mit ihm ein Abkommen treffen*, und eine Tochter von <seinen> Frauen wird er ihm geben, um es* zu verderben. Aber das wird keinen Bestand haben, und es wird ihm nicht gelingen.", footnotes: ["w. in die Gewalt", "T.; Mas. T.: Rechtschaffene sind mit ihm, und er wirkt", "T.; Mas. T.: Rechtschaffene sind mit ihm, und er wirkt", "d. i. das Reich des Südens"] },
      { number: 18, text: "Und er wird sein Angesicht zu den Inseln* wenden und viele einnehmen. Aber ein Feldherr wird seinem Schmähen ein Ende machen; mit einem Fluch wird er ihm sein Schmähen zurückzahlen*.", footnotes: ["o. Küsten", "T.; Mas. T.: ohne ihm sein Schmähen zurückzuzahlen"] },
      { number: 19, text: "Und er wird sein Angesicht den Festungen seines Landes zuwenden und wird stürzen und fallen und nicht <mehr> zu finden sein*.", footnotes: ["℘ Hi 34,24; Ps 37,35.36"] },
      { number: 20, text: "Und es wird an seiner Stelle jemand aufstehen, der einen Eintreiber <von Abgaben>* durch die Herrlichkeit des Königreichs ziehen lässt; aber in wenigen Tagen wird er zerschmettert werden, und zwar weder durch Zorn* noch durch Krieg.", footnotes: ["o. Bedränger; o. Gewalthaber", "Andere üs. mit geringfügiger Änderung: weder offen"] },
      { number: 21, text: "Und an seiner Stelle wird ein Verachteter aufstehen*, auf den man nicht die Würde des Königtums legen wird; und er wird unversehens* kommen und sich durch Heucheleien* des Königtums bemächtigen*.", footnotes: ["℘ Kap. 8,9.23", "w. in Sorglosigkeit; d. h. mitten im Frieden", "w. durch Glätte", "℘ 2Sam 15,2-6"] },
      { number: 22, text: "Und die heranflutenden Streitkräfte werden vor ihm weggeschwemmt und zertrümmert werden, ja sogar ein Fürst des Bundes*.", footnotes: ["℘ Kap. 8,11"] },
      { number: 23, text: "Denn nachdem er sich mit ihm verbündet hat, wird er betrügerisch* handeln und wird hinaufziehen und mit wenig Volk Macht gewinnen*.", footnotes: ["o. hinterlistig", "℘ Kap. 8,24"] },
      { number: 24, text: "Unversehens* wird er in die fetten Gegenden einer Provinz eindringen und tun, was weder seine Väter noch die Väter seiner Väter getan haben: Raub und Plündergut und Besitz wird er ihnen austeilen*, und gegen Festungen plant er seine Anschläge, doch <nur> eine Zeit lang.", footnotes: ["w. in Sorglosigkeit; d. h. mitten im Frieden", "w. ausstreuen"] },
      { number: 25, text: "Und mit einem großen Heer wird er seine Kraft und seinen Mut* gegen den König des Südens aufbieten*. Und <auch> der König des Südens wird sich mit einem großen und überaus starken Heer zum Krieg rüsten. Aber er wird nicht standhalten, denn man wird Anschläge gegen ihn planen.", footnotes: ["w. sein Herz", "w. erwecken"] },
      { number: 26, text: "Und die, die seine Tafelkost essen, werden ihn zerbrechen; und sein Heer flutet <auseinander>, und viele werden erschlagen fallen." },
      { number: 27, text: "Und die beiden Könige: ihre Herzen <werden> auf Bosheit <bedacht sein>, und an einem Tisch werden sie Lügen reden*. Aber es wird nicht gelingen, denn das Ende <verzögert sich> noch bis zur bestimmten Zeit*.", footnotes: ["℘ Spr 12,20", "o. denn noch gibt es ein Ende zur bestimmten Zeit\n℘ Kap. 8,17.19"] },
      { number: 28, text: "Und er wird mit großem Reichtum in sein Land zurückkehren*, und sein Herz wird gegen den heiligen Bund <gerichtet> sein; und er wird <entsprechend> handeln und in sein Land zurückkehren.", footnotes: ["℘ Kap. 8,12"] },
      { number: 29, text: "Zur bestimmten Zeit wird er wieder nach Süden ziehen, aber es wird beim zweiten Mal nicht <so> sein wie beim ersten Mal." },
      { number: 30, text: "Denn Schiffe aus Kittim* werden gegen ihn kommen. Und er wird verzagen und umkehren; aber er wird den heiligen Bund verfluchen und <entsprechend> handeln: er wird umkehren und sein Augenmerk auf die richten, die den heiligen Bund verlassen.", footnotes: ["d. i. Zypern\n℘ 4Mo 24,24; Hes 27,6"] },
      { number: 31, text: "Und Streitkräfte von ihm werden dastehen; und sie werden das Heiligtum, die Bergfeste entweihen und werden das regelmäßige <Opfer> abschaffen und den verwüstenden Gräuel aufstellen*.", footnotes: ["℘ Kap. 8,11.13"] },
      { number: 32, text: "Und diejenigen, die sich am Bund schuldig machen*, wird er durch glatte Worte zum Abfall verleiten. Aber das Volk, das seinen Gott kennt, wird sich stark erweisen und entsprechend handeln*.", footnotes: ["o. die am Bund gottlos handeln", "℘ Neh 4,14"] },
      { number: 33, text: "Und die Verständigen* des Volkes werden die Vielen unterweisen*; aber sie werden stürzen durch Schwert und Flamme, durch Gefangenschaft und Beraubung — eine Zeit lang.", footnotes: ["℘ Kap. 12,3.10", "o. werden den Vielen zur Einsicht verhelfen"] },
      { number: 34, text: "Und während sie stürzen, wird ihnen mit einer kleinen Hilfe geholfen werden. Doch viele werden sich ihnen heuchlerisch anschließen." },
      { number: 35, text: "Und von den Verständigen werden <einige> stürzen, damit unter ihnen geläutert und geprüft und gereinigt werde* bis zur Zeit des Endes. Denn <es verzögert sich> noch bis zur bestimmten Zeit.", footnotes: ["℘ Kap. 12,10; Sach 13,9; Offb 7,14"] },
      { number: 36, text: "Und der König* wird nach seinem Belieben handeln, und er wird sich erheben und sich groß machen gegen jeden Gott*, und gegen den Gott der Götter wird er unerhörte Reden führen*. Und er wird Erfolg haben, bis die Verfluchung vollendet ist*, denn das Festbeschlossene wird vollzogen*.", footnotes: ["℘ Jes 30,33; 57,9; Sach 11,16", "℘ Jes 14,14; Hes 28,2; 2Thes 2,4", "℘ Kap. 7,8.25; 8,24.25", "℘ Kap. 8,19; Jes 10,5.6.23.25", "℘ Kap. 9,26.27"] },
      { number: 37, text: "Und <selbst> auf den Gott* seiner Väter wird er nicht achten, und weder auf den Schatz der Frauen* noch auf irgendeinen Gott wird er achten; sondern er wird sich über alles erheben*.", footnotes: ["o. auf die Götter", "d. i. der Name einer Gottheit; vgl. Hes 8,14", "℘ Jes 14,14; Hes 28,2; 2Thes 2,4"] },
      { number: 38, text: "Und stattdessen wird er den Gott der Festungen ehren. Und den Gott, den seine Väter nicht gekannt haben, wird er mit Gold und mit Silber und mit Edelsteinen und mit Kostbarkeiten ehren." },
      { number: 39, text: "Und er wird gegen die starken Festungen* vorgehen mit einem fremden Gott. Wer <ihn> anerkennt*, dem wird er viel Ehre erweisen. Und er wird solchen Leuten* Herrschaft verleihen über die vielen und <ihnen> das Land zum Lohn austeilen.", footnotes: ["w. gegen die Befestigungen der Festungen", "w. ansieht", "w. ihnen"] },
      { number: 40, text: "Und zur Zeit des Endes wird der König des Südens mit ihm zusammenstoßen, und der König des Nordens wird gegen ihn anstürmen mit Wagen und mit Reitern und mit vielen Schiffen. Und er wird in die Länder eindringen und wird <sie> überschwemmen und überfluten*.", footnotes: ["℘ Hes 38,9"] },
      { number: 41, text: "Und er wird in das Land der Zierde* eindringen, wobei vieles stürzen wird*. Diese aber werden seiner Hand entrinnen: Edom und Moab und die Besten* der Söhne Ammon*.", footnotes: ["d. i. Israel\n℘ V. 16.20", "o. straucheln wird", "o. der wichtigste Teil; w. das Erste. — Die syr. Üs. liest: der Rest", "℘ Jes 11,14"] },
      { number: 42, text: "Und er wird seine Hand an die Länder legen, und für das Land Ägypten wird es kein Entrinnen geben." },
      { number: 43, text: "Und er wird die Schätze an Gold und Silber und alle Kostbarkeiten Ägyptens in seine Gewalt bringen, und Libyer und Kuschiter werden in seinem Gefolge sein." },
      { number: 44, text: "Aber Gerüchte von Osten und von Norden her werden ihn erschrecken; und er wird mit großem Zorn ausziehen, um viele zu vernichten und <an ihnen> den Bann zu vollstrecken." },
      { number: 45, text: "Und er wird seine Königszelte aufschlagen* zwischen dem Meer* und dem Berg der heiligen Zierde*. Dann wird er an sein Ende kommen, und niemand wird ihm helfen*.", footnotes: ["w. die <Pflöcke der> Zelte seines Palastes einschlagen; o. die Zelte seiner Rüstkammern aufschlagen; d. h. seine Kriegszelte", "w. zwischen den Meeren\n℘ 4Mo 34,5.6", "d. i. Israel\n℘ V. 16; Ps 48,2.3", "℘ Kap. 7,26; 8,25; Jes 10,12; 2Thes 2,8"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und in jener Zeit wird Michael* auftreten, der große Fürst, der für die Söhne deines Volkes eintritt. Und es wird eine Zeit der Bedrängnis sein, wie sie <noch> nie gewesen ist, seitdem <irgend>eine Nation entstand bis zu jener Zeit*. Und in jener Zeit wird dein Volk gerettet werden*, jeder, den man im Buch aufgeschrieben findet*.", footnotes: ["℘ Kap. 10,13.21", "℘ Mt 24,21", "℘ Jer 30,7.10", "℘ Lk 10,20"] },
      { number: 2, text: "Und viele von denen, die im Land des Staubes* schlafen, werden aufwachen*; die einen zu ewigem Leben und die anderen zur Schande, zu ewigem Abscheu*.", footnotes: ["LXX und Vulg.: im Staub der Erde", "℘ Jes 26,19", "℘ Mt 25,46; Joh 5,28.29"] },
      { number: 3, text: "Und die Verständigen* werden leuchten wie der Glanz der Himmelsfeste*; und die, welche die vielen zur Gerechtigkeit gewiesen haben*, <leuchten> wie die Sterne immer und ewig*.", footnotes: ["℘ Kap. 11,33.35", "℘ Ri 5,31; Spr 3,35; Mt 13,43", "℘ Pred 12,9", "℘ 1Kor 15,40-44"] },
      { number: 4, text: "Und du, Daniel, halte die Worte geheim* und versiegle das Buch* bis zur Zeit des Endes*! Viele werden <suchend> umherstreifen*, und die Erkenntnis* wird sich mehren.", heading: "Weissagung über die Dauer der endzeitlichen Drangsal", footnotes: ["w. verschließe die Worte", "℘ Kap. 8,26; Jes 8,16", "℘ Kap. 8,17; Offb 5,1", "o. werden <es> durchforschen", "Andere üs. mit Textänderung: das Böse"] },
      { number: 5, text: "Und ich, Daniel, sah: Und siehe, zwei andere standen da, einer hier am Ufer des Stromes* und einer dort am Ufer des Stromes.", footnotes: ["d. i. der Tigris\n℘ Kap. 10,4-6"] },
      { number: 6, text: "Und einer sagte zu dem in Leinen gekleideten Mann, der oben über dem Wasser des Stromes war: Wann ist das Ende dieser außergewöhnlichen Ereignisse*?", footnotes: ["℘ Kap. 8,13"] },
      { number: 7, text: "Und ich hörte den in Leinen gekleideten Mann, der oben über dem Wasser des Stromes war, und er erhob seine Rechte und seine Linke zum Himmel und schwor bei dem, der ewig lebt*: Zeit, Zeiten und eine halbe <Zeit>*! Und wenn die Zerschlagung der Kraft des heiligen Volkes abgeschlossen sein wird*, wird alles dies vollendet werden*.", footnotes: ["℘ Kap. 4,31; 5Mo 32,40; Offb 10,5.6", "o. eine Frist, zwei Fristen und eine halbe <Frist>\n℘ Kap. 7,25", "℘ 5Mo 32,36; Lk 21,24", "℘ Kap. 7,21; Offb 13,5.7"] },
      { number: 8, text: "Und ich hörte es, aber ich verstand es nicht; und ich sagte: Mein Herr, was wird der Ausgang davon sein?" },
      { number: 9, text: "Und er sagte: Geh hin, Daniel! Denn die Worte sollen geheim gehalten* und versiegelt sein bis zur Zeit des Endes.", footnotes: ["w. verschlossen"] },
      { number: 10, text: "Viele werden geprüft und gereinigt und geläutert werden*. Aber die Gottlosen werden <weiter> gottlos handeln. Und die Gottlosen werden es alle nicht verstehen, die Verständigen aber werden es verstehen*.", footnotes: ["℘ Kap. 11,35", "℘ Kap. 11,33; Ps 107,43; Hos 14,10; Lk 7,35"] },
      { number: 11, text: "Und von der Zeit an, in der das regelmäßige <Opfer>* abgeschafft wird, um den verwüstenden Gräuel einzusetzen*, sind es 1 290 Tage.", footnotes: ["℘ Kap. 8,11; 2Mo 29,38", "℘ Kap. 8,11.13; Mt 24,15"] },
      { number: 12, text: "Glücklich, wer ausharrt und 1 335 Tage erreicht!" },
      { number: 13, text: "Du aber geh hin auf das Ende zu! Und du wirst ruhen* und wirst auferstehen zu deinem Los* am Ende der Tage*.", footnotes: ["℘ 2Mo 33,14; Ps 16,9; Offb 14,13", "o. zu deinem Anteil", "℘ Joh 11,24"] },
    ]},
  ]
};
